constexpr std::uint32_t ExecutorBox64MappedEntryAbiVersion = 4;
constexpr std::uint32_t ExecutorBox64MappedEntryMaxSegments = 64;
// The mapped-entry primary thread executes on a separate guest stack instead of the native host
// stack used by desktop shadPS4.  Keep its capacity aligned with JIT's own guest-stack
// fallback so deep native-game call chains do not run off the synthetic 1 MiB mapping.
constexpr std::size_t ExecutorBox64InitialStackSize = 8 * 1024 * 1024;
// Short-lived module lifecycle/callback invocations do not share the primary stack and retain their
// existing bounded allocation.
constexpr std::size_t ExecutorBox64LifecycleStackSize = 1024 * 1024;
constexpr std::uint32_t ExecutorBox64MappedEntryTimeoutMs = 3000;
constexpr std::uint32_t ExecutorBox64HleBridgeSyscall = 0x5ad00001u;
constexpr std::uint32_t ExecutorBox64GuestExitSyscall = 0x5ad00002u;
constexpr std::uint32_t ExecutorBox64MappedEntryFlagInProcess = 1u << 0;
constexpr std::size_t ExecutorBox64HleTrampolineSize = 512;  // safe-stack prologue + guest callee-saved spill
constexpr std::size_t ExecutorBox64HleTrampolineSlabSize = 2 * 1024 * 1024;
// HLE safe scratch-stack pool: HLE thunks grab a unique slot here (lock xadd) instead of using the
// guest RSP as sideband storage, which can point into mono's SGen heap and corrupt GC objects.
constexpr std::size_t ExecutorBox64HleSafePoolSize = 256 * 1024 * 1024;  // power-of-2; 64K x 0x1000 slots
constexpr std::uint32_t ExecutorBox64HleSafeSlotSize = 0x1000;
constexpr std::uint32_t ExecutorBox64HleSafeSlotRsp = 0x800;  // leave room both below and above FEX's thunk frame
constexpr std::uint32_t ExecutorBox64HleStackScratchSize = 0x1000;
constexpr std::size_t ExecutorBox64HleSidebandSlotSize = 96;
constexpr std::size_t ExecutorBox64HleSidebandSlabSize = 64 * 1024;
