#ifdef __ANDROID__
void RecordJitSignalBridgeFailure(const char* stage, std::uint64_t handler,
                                       std::uint64_t arg0, std::uint64_t arg1,
                                       std::uint64_t arg2, const char* detail) {
    char line[1024];
    const int length = std::snprintf(
        line, sizeof(line),
        "stage=%s handler=0x%llx arg0=0x%llx arg1=0x%llx arg2=0x%llx detail=%s\n",
        stage ? stage : "unknown", static_cast<unsigned long long>(handler),
        static_cast<unsigned long long>(arg0), static_cast<unsigned long long>(arg1),
        static_cast<unsigned long long>(arg2), detail ? detail : "none");
    const int fd = ::open(
        "/data/data/app.lsx4.android/files/executor-jit-signal-failure.log",
        O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
    if (fd >= 0) {
        if (length > 0) {
            (void)::write(fd, line,
                          std::min<std::size_t>(static_cast<std::size_t>(length),
                                                sizeof(line) - 1));
        }
        ::close(fd);
    }
}
#endif

