int TryGetCurrentGuestRegsSnapshot(ExecutorBox64GuestRegsSnapshot& out) {
    if (RuntimeGuestJitActive()) {
        auto* state = Executor::Jit::CurrentMachineImage();
        if (state == nullptr) {
            out = {};
            return -1;
        }
        FillBox64RegsFromJitState(*state, out);
        return 0;
    }
    if (g_box64_get_current_guest_regs == nullptr) {
        out = {};
        return -1;
    }
    return g_box64_get_current_guest_regs(&out, sizeof(out));
}

void PublishCurrentJitGcRegisterRootsAtHleBoundary() {
    if (!ExecutorGcGuestRootsEnabled() || !RuntimeGuestJitActive()) {
        return;
    }

    ExecutorBox64GuestRegsSnapshot snapshot{};
    if (TryGetCurrentGuestRegsSnapshot(snapshot) == 0) {
        // Mono's stop-the-world signal only visits threads registered with the managed runtime.
        // FMOD and other native guest workers can therefore keep their only live mspace pointer in
        // an emulated callee-saved GPR without ever reaching the signal-side publisher.  Every guest
        // thread crosses this boundary for HLE calls, so retain its latest complete x86 register
        // image in the already registered snapshot slab before native HLE can block or trigger GC.
        executor_lsx4_android_publish_guest_gc_register_roots(&snapshot, sizeof(snapshot));
    }
}

