// The Android shared-library launcher does not enter Core::Emulator::Run.  Keep its filesystem and
// configuration bootstrap equivalent to the desktop launcher explicitly: otherwise game-specific
// settings silently remain at the compiled defaults even when a valid <title>.toml exists.  Rebase
// every derived path together so
// shader/pipeline caches, logs, patches and per-title configuration all share one canonical tree.
void ConfigureAndroidRuntimeUserPathsAndBaseConfig() {
    if (g_root.empty()) {
        return;
    }

    namespace FS = Common::FS;
    const auto legacy_user_dir = std::filesystem::path(g_root);
    const auto user_dir = legacy_user_dir / "native";
    struct UserSubdirectory {
        FS::PathType type;
        const char* name;
    };
    constexpr std::array UserSubdirectories{
        UserSubdirectory{FS::PathType::LogDir, FS::LOG_DIR},
        UserSubdirectory{FS::PathType::ScreenshotsDir, FS::SCREENSHOTS_DIR},
        UserSubdirectory{FS::PathType::ShaderDir, FS::SHADER_DIR},
        UserSubdirectory{FS::PathType::TempDataDir, FS::TEMPDATA_DIR},
        UserSubdirectory{FS::PathType::GameDataDir, FS::GAMEDATA_DIR},
        UserSubdirectory{FS::PathType::SysModuleDir, FS::SYSMODULES_DIR},
        UserSubdirectory{FS::PathType::DownloadDir, FS::DOWNLOAD_DIR},
        UserSubdirectory{FS::PathType::CapturesDir, FS::CAPTURES_DIR},
        UserSubdirectory{FS::PathType::CheatsDir, FS::CHEATS_DIR},
        UserSubdirectory{FS::PathType::PatchesDir, FS::PATCHES_DIR},
        UserSubdirectory{FS::PathType::MetaDataDir, FS::METADATA_DIR},
        UserSubdirectory{FS::PathType::CustomTrophy, FS::CUSTOM_TROPHY},
        UserSubdirectory{FS::PathType::CustomConfigs, FS::CUSTOM_CONFIGS},
        UserSubdirectory{FS::PathType::CacheDir, FS::CACHE_DIR},
        UserSubdirectory{FS::PathType::FontsDir, FS::FONTS_DIR},
    };

    std::error_code error;
    std::filesystem::create_directories(user_dir, error);
    if (error) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_CONFIG_BRIDGE] phase=rebase status=failed user=%s error=%s",
                  user_dir.string().c_str(), error.message().c_str());
        return;
    }
    FS::SetUserPath(FS::PathType::UserDir, user_dir);
    for (const auto& directory : UserSubdirectories) {
        const auto path = user_dir / directory.name;
        error.clear();
        std::filesystem::create_directories(path, error);
        if (!error) {
            FS::SetUserPath(directory.type, path);
        }
    }

    // Older Android launchers and the device-side test tooling wrote PC-style per-title files
    // directly below lsx4-home/custom_configs.  The native runtime intentionally uses
    // lsx4-home/native as its canonical shadPS4 UserDir, so silently rebasing CustomConfigs
    // without carrying those files forward drops compatibility settings (notably GPU shared-memory
    // readback policy) and makes a previously working title regress to compiled defaults.
    //
    // Import every legacy .toml exactly once and never overwrite a canonical file.  This is a
    // format/path compatibility bridge, not a title-specific fallback: after the copy all normal
    // Config::load/save paths continue to use the one canonical native tree.
    const auto legacy_custom_configs = legacy_user_dir / FS::CUSTOM_CONFIGS;
    const auto canonical_custom_configs = user_dir / FS::CUSTOM_CONFIGS;
    std::size_t legacy_configs_seen = 0;
    std::size_t legacy_configs_imported = 0;
    std::size_t legacy_config_errors = 0;
    error.clear();
    if (std::filesystem::is_directory(legacy_custom_configs, error) && !error) {
        std::filesystem::directory_iterator iterator(legacy_custom_configs, error);
        const std::filesystem::directory_iterator end;
        while (!error && iterator != end) {
            const auto& entry = *iterator;
            std::error_code entry_error;
            if (entry.is_regular_file(entry_error) && !entry_error &&
                entry.path().extension() == ".toml") {
                ++legacy_configs_seen;
                const auto destination = canonical_custom_configs / entry.path().filename();
                std::error_code copy_error;
                if (!std::filesystem::exists(destination, copy_error) && !copy_error &&
                    std::filesystem::copy_file(entry.path(), destination,
                                               std::filesystem::copy_options::none,
                                               copy_error)) {
                    ++legacy_configs_imported;
                } else if (copy_error) {
                    ++legacy_config_errors;
                }
            }
            iterator.increment(error);
        }
        if (error) {
            ++legacy_config_errors;
        }
    } else if (error) {
        ++legacy_config_errors;
    }
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_CONFIG_BRIDGE] phase=legacy_custom_configs source=%s target=%s "
              "seen=%zu imported=%zu errors=%zu",
              legacy_custom_configs.string().c_str(),
              canonical_custom_configs.string().c_str(), legacy_configs_seen,
              legacy_configs_imported, legacy_config_errors);

    const auto base_config = user_dir / "config.toml";
    Config::load(base_config);
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_CONFIG_BRIDGE] phase=base status=loaded user=%s config=%s "
              "readbacksMode=%d",
              user_dir.string().c_str(), base_config.string().c_str(),
              Config::getReadbacksMode());
}

#ifdef __ANDROID__
bool IsSupportedAndroidFixedSurfaceSize(const int width, const int height) {
    return (width == 320 && height == 180) || (width == 480 && height == 270) ||
           (width == 640 && height == 360) || (width == 960 && height == 540) ||
           (width == 1280 && height == 720) || (width == 1920 && height == 1080) ||
           (width == 2880 && height == 1620);
}

void ApplyAndroidFixedSurfaceToGameConfig(std::string_view title_id) {
    if (!g_surface_attached || g_native_window == nullptr || g_surface_width <= 0 ||
        g_surface_height <= 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_ANDROID_INTERNAL_RESOLUTION] status=skipped "
                  "reason=surface_unavailable title=%.*s width=%d height=%d",
                  static_cast<int>(title_id.size()), title_id.data(), g_surface_width,
                  g_surface_height);
        return;
    }

    if (!IsSupportedAndroidFixedSurfaceSize(g_surface_width, g_surface_height)) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_ANDROID_INTERNAL_RESOLUTION] status=skipped "
                  "reason=not_a_supported_fixed_size title=%.*s width=%d height=%d",
                  static_cast<int>(title_id.size()), title_id.data(), g_surface_width,
                  g_surface_height);
        return;
    }

    Config::setInternalScreenWidth(static_cast<u32>(g_surface_width), true);
    Config::setInternalScreenHeight(static_cast<u32>(g_surface_height), true);
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_ANDROID_INTERNAL_RESOLUTION] status=applied title=%.*s "
              "width=%u height=%u source=android_fixed_surface",
              static_cast<int>(title_id.size()), title_id.data(),
              Config::getInternalScreenWidth(), Config::getInternalScreenHeight());
}
#endif

void LoadAndroidGameSpecificConfig(std::string_view title_id) {
    if (title_id.empty()) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_CONFIG_BRIDGE] phase=game status=skipped reason=empty_title");
        return;
    }
    const auto config = Common::FS::GetUserPath(Common::FS::PathType::CustomConfigs) /
                        (std::string(title_id) + ".toml");
    std::error_code error;
    const bool exists = std::filesystem::is_regular_file(config, error);
    Config::load(config, true);
#ifdef __ANDROID__
    ApplyAndroidFixedSurfaceToGameConfig(title_id);
#endif
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_CONFIG_BRIDGE] phase=game status=%s title=%.*s config=%s "
              "readbacksMode=%d readbackLinearImages=%d",
              exists && !error ? "loaded" : "missing", static_cast<int>(title_id.size()),
              title_id.data(), config.string().c_str(), Config::getReadbacksMode(),
              Config::readbackLinearImages() ? 1 : 0);
}

