extern "C" bool executor_lsx4_android_should_suppress_guest_thread(void* start_routine,
                                                                       void* arg,
                                                                       const char* name) {
    (void)arg;
    // On Android every *guest* pthread MUST run through the mapped guest-thread path
    // (RunBox64GuestThread -> run_guest_thread). In the FEX route this registers the thread's FEX
    // TLS/alt-stack, and in JIT it dispatches the x86 start routine through the reconstructed
    // AArch64 JIT. The fallthrough RunThread path calls start_routine() directly as host code; on
    // arm64 that executes the guest x86 bytes as arm64 -> SIGILL/ILL_ILLOPC (host pc == guest addr).
    // That is exactly what kills JIT worker threads once Mono creates Thread2.
    //
    // A prior name filter returned false (=> raw RunThread) for threads whose name contained
    // Worker/GC/Mono/SGen/Finalizer/Marker/Suspend. "UnityGfxDeviceWorker" matches "Worker", so it
    // took the crashing path. That filter was only ever safe in the old box64-helper era; with the
    // FEXCore embed the raw path is always a crash. (The SGen major-heap-block-metadata concern
    // that motivated the filter was actually fixed by the libc-mspace reservation, not by the
    // thread run path.)
    //
    // Do not route shadPS4's own HOST_CALL pthreads through that path. Kernel::Thread::Run also uses
    // posix_pthread_create, with an AArch64 RunWrapper address. The old unconditional JIT
    // decision sent that host address to the x86 decoder; run_guest_thread then papered over the
    // failed address lookup with g_last_module_handle and decoded AArch64 bytes as x86 (typically an
    // immediate HLT/decode failure). A real guest pthread entry belongs to one of Linker's executable
    // modules, whereas a HOST_CALL entry does not. Keep the two thread domains disjoint, matching
    // upstream shadPS4's native host-thread contract.
    const bool mapped_backend_active =
        RuntimeGuestJitActive() || g_box64_guest_entry_active.load(std::memory_order_acquire);
    if (!mapped_backend_active || start_routine == nullptr) {
        return false;
    }
    const auto start_address = reinterpret_cast<std::uint64_t>(start_routine);
    auto* linker = Common::Singleton<Core::Linker>::Instance();
    const bool is_guest_entry = linker != nullptr && linker->FindByAddress(start_address) != nullptr;
    if (!is_guest_entry) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_HOST_THREAD_ROUTE] native start=%p name=%s jit=%d; "
                  "bypassing guest x86 dispatcher",
                  start_routine, name ? name : "<unnamed>", RuntimeGuestJitActive() ? 1 : 0);
    }
    return is_guest_entry;
}

extern "C" void executor_lsx4_android_note_suppressed_guest_thread(void* thread,
                                                                       void* start_routine,
                                                                       void* arg,
                                                                       const char* name) {
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_GUEST_THREAD] suppressed guest pthread=%p start=%p arg=%p name=%s",
              thread, start_routine, arg, name ? name : "<unnamed>");
}

extern "C" bool executor_lsx4_android_should_suppress_guest_once(void* once_control,
                                                                     void* init_routine) {
    (void)once_control;
    (void)init_routine;
    return g_box64_guest_entry_active.load(std::memory_order_acquire) &&
           g_box64_run_mapped_function == nullptr;
}

extern "C" void executor_lsx4_android_note_suppressed_guest_once(void* once_control,
                                                                     void* init_routine) {
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_GUEST_ONCE] suppressed guest pthread_once=%p init=%p",
              once_control, init_routine);
}

extern "C" bool executor_lsx4_android_should_auto_allocate_pthread_key(int key) {
    return g_box64_guest_entry_active.load(std::memory_order_acquire) && key >= 0 && key < 256;
}

extern "C" void executor_lsx4_android_note_auto_allocated_pthread_key(int key) {
    static std::atomic_int log_budget{32};
    if (log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_GUEST_TLS] auto-allocated pthread key=%d for active guest",
                  key);
    }
}

std::string JsonEscape(const std::string& value) {
    std::string out;
    out.reserve(value.size() + 8);
    for (const char ch : value) {
        switch (ch) {
        case '\\':
            out += "\\\\";
            break;
        case '"':
            out += "\\\"";
            break;
        case '\n':
            out += "\\n";
            break;
        case '\r':
            out += "\\r";
            break;
        case '\t':
            out += "\\t";
            break;
        default:
            out += ch;
            break;
        }
    }
    return out;
}

std::filesystem::path FirmwareModulesRoot() {
    if (g_root.empty()) {
        return {};
    }
    return std::filesystem::path(g_root) / "sys_modules";
}

void AppendJsonStringArray(std::ostringstream& out, const std::vector<std::string>& values) {
    out << '[';
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) {
            out << ',';
        }
        out << '"' << JsonEscape(values[i]) << '"';
    }
    out << ']';
}

std::string BuildFirmwareSupportStatusJson() {
    if (g_root.empty()) {
        return R"({"enabled":false,"reason":"runtime not initialized"})";
    }

    try {
        const auto root = FirmwareModulesRoot();
        const bool root_exists = std::filesystem::exists(root);
        std::vector<std::string> present;
        std::vector<std::string> missing;
        present.reserve(ExecutorSupportedFirmwareModules.size());
        missing.reserve(ExecutorSupportedFirmwareModules.size());

        for (const char* module : ExecutorSupportedFirmwareModules) {
            const auto module_path = root / module;
            if (root_exists && std::filesystem::exists(module_path)) {
                present.emplace_back(module);
            } else {
                missing.emplace_back(module);
            }
        }

        int game_specific_dir_count = 0;
        if (root_exists) {
            for (const auto& entry : std::filesystem::directory_iterator(root)) {
                std::error_code ec;
                if (entry.is_directory(ec)) {
                    ++game_specific_dir_count;
                }
            }
        }

        std::ostringstream out;
        const auto game_specific_pattern = (root / "<TITLE_ID>" / "<module>.sprx").string();

        out << R"({"enabled":true,)"
            << R"("policy":"hle-first-user-provided-legal-dumps-only",)"
            << R"("sysModulesPath":")" << JsonEscape(root.string()) << R"(",)"
            << R"("gameSpecificPathPattern":")" << JsonEscape(game_specific_pattern) << R"(",)"
            << R"("supportedCount":)" << ExecutorSupportedFirmwareModules.size() << ','
            << R"("presentCount":)" << present.size() << ','
            << R"("missingCount":)" << missing.size() << ','
            << R"("present":)";
        AppendJsonStringArray(out, present);
        out << R"(,"missing":)";
        AppendJsonStringArray(out, missing);
        out << R"(,"gameSpecificDirCount":)" << game_specific_dir_count << ','
            << R"("legalNotice":"firmware modules are not bundled; import user-owned PS4 dumps",)"
            << R"("nextStep":"import legal dumps into app sandbox or use upstream HLE fallback"})";
        return out.str();
    } catch (const std::exception& e) {
        return std::string(R"({"enabled":false,"reason":"status probe failed","error":")") +
               JsonEscape(e.what()) + R"("})";
    } catch (...) {
        return R"({"enabled":false,"reason":"status probe failed","error":"unknown"})";
    }
}

void ConfigureFirmwareSupportLocked() {
    if (g_root.empty()) {
        g_firmware_status = R"({"enabled":false,"reason":"runtime not initialized"})";
        return;
    }

    try {
        const auto root = FirmwareModulesRoot();
        std::filesystem::create_directories(root);
        Config::setSysModulesPath(root);
        g_firmware_status = BuildFirmwareSupportStatusJson();
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] sys_modules=%s",
                  root.string().c_str());
    } catch (const std::exception& e) {
        g_firmware_status =
            std::string(R"({"enabled":false,"reason":"sys_modules staging failed","error":")") +
            JsonEscape(e.what()) + R"("})";
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] staging failed: %s", e.what());
    } catch (...) {
        g_firmware_status =
            R"({"enabled":false,"reason":"sys_modules staging failed","error":"unknown"})";
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] staging failed: unknown");
    }
}

std::string Hex64(const std::uint64_t value) {
    std::ostringstream out;
    out << "0x" << std::hex << value;
    return out.str();
}

std::string LocalBytesHex(const std::uint8_t* data, const std::size_t size) {
    if (data == nullptr || size == 0) {
        return "";
    }
    std::ostringstream out;
    static constexpr char Hex[] = "0123456789abcdef";
    for (std::size_t i = 0; i < size; ++i) {
        if (i != 0) {
            out << ' ';
        }
        const std::uint8_t byte = data[i];
        out << Hex[(byte >> 4) & 0xf] << Hex[byte & 0xf];
    }
    return out.str();
}

std::string ProtString(const std::int32_t prot) {
    std::string out;
    out += (prot & PF_READ) ? 'r' : '-';
    out += (prot & PF_WRITE) ? 'w' : '-';
    out += (prot & PF_EXEC) ? 'x' : '-';
    return out;
}

bool GuestAddressInsideModule(const Core::Module& module, const std::uint64_t address) {
    const auto info = module.GetModuleInfo();
    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        const std::uint64_t begin = segment.address;
        const std::uint64_t end = begin + segment.size;
        if (address >= begin && address < end) {
            return true;
        }
    }
    return false;
}

bool RestoreMappedEntryExecutableProtections(const Core::Module& module, std::string& error) {
    static std::atomic_int trace_budget{2};
    const bool trace_protections = trace_budget.fetch_sub(1, std::memory_order_relaxed) > 0;
    const auto info = module.GetModuleInfo();
    constexpr std::uint64_t PageSize = 0x1000;
    const std::uint64_t entry = module.GetEntryAddress();
    bool entry_in_segment = false;

    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        if (segment.size == 0) {
            continue;
        }

        const std::uint64_t begin = segment.address;
        const std::uint64_t end = begin + segment.size;
        if (entry >= begin && entry < end) {
            entry_in_segment = true;
            if (trace_protections) {
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_MAPPED_ENTRY_PROT] entrySegment index=%u addr=%p size=0x%llx prot=%s entry=%p",
                          i, reinterpret_cast<void*>(begin),
                          static_cast<unsigned long long>(segment.size),
                          ProtString(segment.prot).c_str(), reinterpret_cast<void*>(entry));
            }
        }

        if ((segment.prot & PF_EXEC) == 0) {
            continue;
        }

        const std::uint64_t page_base = Common::AlignDown(begin, PageSize);
        const std::uint64_t page_end = Common::AlignUp(end, PageSize);
        const std::uint64_t page_size = page_end - page_base;

        int host_prot = PROT_NONE;
        if (segment.prot & PF_READ) {
            host_prot |= PROT_READ;
        }
        if (segment.prot & PF_WRITE) {
            host_prot |= PROT_WRITE;
        }
        if (segment.prot & PF_EXEC) {
            host_prot |= PROT_EXEC;
        }

        errno = 0;
        const int rc = ::mprotect(reinterpret_cast<void*>(page_base), page_size, host_prot);
        if (trace_protections || rc != 0) {
            NativeLog(rc == 0 ? ANDROID_LOG_INFO : ANDROID_LOG_ERROR,
                      "[EXECUTOR_MAPPED_ENTRY_PROT] execProtect index=%u addr=%p size=0x%llx prot=%s rc=%d errno=%d",
                      i, reinterpret_cast<void*>(page_base),
                      static_cast<unsigned long long>(page_size), ProtString(segment.prot).c_str(),
                      rc, rc == 0 ? 0 : errno);
        }
        if (rc != 0) {
            error = std::string("mprotect executable segment failed index=") + std::to_string(i) +
                    " errno=" + std::to_string(errno) + " error=" + std::strerror(errno);
            return false;
        }
    }

    if (!entry_in_segment && trace_protections) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_PROT] entryOutsideSegments entry=%p segmentCount=%u",
                  reinterpret_cast<void*>(entry), info.num_segments);
    }

    return true;
}

template <typename Segment>
bool SegmentContainedBy(const Segment& inner, const Segment& outer) {
    if (inner.size == 0 || outer.size == 0) {
        return false;
    }
    const std::uint64_t inner_begin = inner.address;
    const std::uint64_t inner_end = inner.address + inner.size;
    const std::uint64_t outer_begin = outer.address;
    const std::uint64_t outer_end = outer.address + outer.size;
    return inner_begin >= outer_begin && inner_end <= outer_end;
}

std::string GuestBytesHex(const std::uint64_t address, const std::size_t size);
std::uint64_t GuestReturnAddress(const std::uint64_t guest_rsp);
bool ExecutorEnvFlag(const char* name);
bool HleNameMatches(const char* name, const char* plain, const char* encoded);
bool IsLibcCompareHleTarget(const char* name, const char* symbol_name);

std::uint64_t ModuleBaseAddress(const Core::Module& module) {
    const auto info = module.GetModuleInfo();
    std::uint64_t base = 0;
    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        if (segment.size == 0) {
            continue;
        }
        if (base == 0 || segment.address < base) {
            base = segment.address;
        }
    }
    return base;
}

bool ShouldBypassKnownStoreHelperThread(const Core::Module& module, const std::uint64_t start) {
    const std::string path = module.file.string();
    if (path.find("ps4-store") == std::string::npos &&
        path.find("homebrew.elf") == std::string::npos) {
        return false;
    }

    const std::uint64_t base = ModuleBaseAddress(module);
    if (base == 0 || start < base) {
        return false;
    }

    // PS4 Store R2 starts one helper pthread at base+0x1ba9c0 before EGL setup.
    // That address falls inside a branch displacement in this stripped build and
    // aborts immediately under Box64. Treat it as non-critical background work
    // (network/update/icon helper) so the main UI path can continue to Piglet.
    return start - base == 0x1ba9c0;
}

bool IsItemzCoreModule(const Core::Module& module) {
    return module.file.string().find("ItemzCore.self") != std::string::npos;
}

bool ShouldBypassKnownItemzCoreUtilityThread(const Core::Module& module,
                                             const std::uint64_t start) {
    if (!IsItemzCoreModule(module)) {
        return false;
    }

    const std::uint64_t base = ModuleBaseAddress(module);
    if (base == 0 || start < base) {
        return false;
    }

    const std::uint64_t offset = start - base;

    // ItemzCore starts several utility/service pthreads around the first UI
    // frame. On the Android emulator these background routines currently trip
    // libndk_translation/berberis signal handling through rt_sigaction before
    // the launcher render loop can present text/icons. Keep the main render
    // path alive and treat these as non-critical until the signal path is
    // translated by the Box64 syscall bridge.
    return offset == 0x499f50 || offset == 0x49a300 || offset == 0x49a370 ||
           offset == 0x49a4e0 || offset == 0x49a550;
}

bool IsKnownStoreInstallWorkerThread(const Core::Module& module, const std::uint64_t start) {
    const std::string path = module.file.string();
    if (path.find("ps4-store") == std::string::npos &&
        path.find("homebrew.elf") == std::string::npos) {
        return false;
    }

    const std::uint64_t base = ModuleBaseAddress(module);
    if (base == 0 || start < base) {
        return false;
    }

    // Store R2 dl_from_url_v2() launches start_routine2 at base+0x51b00 after
    // the local-file transport gate accepts a package URL. This is the first
    // thread that can reach pkginstall/AppInstUtil/BGFT, so it must run through
    // Box64 instead of being treated like the non-critical Store background
    // workers used during UI bootstrap.
    return start - base == 0x51b00;
}

Core::Module* FindGuestModuleByAddress(const std::uint64_t address) {
    auto* linker = Common::Singleton<Core::Linker>::Instance();
    return linker ? linker->FindByAddress(address) : nullptr;
}

std::uint64_t GuestModuleOffset(const Core::Module& module, const std::uint64_t address) {
    const std::uint64_t base = ModuleBaseAddress(module);
    return base && address >= base ? address - base : 0;
}

bool ParseHexMessageField(const std::string_view message, const std::string_view key,
                          std::uint64_t& out) {
    const std::size_t key_pos = message.find(key);
    if (key_pos == std::string_view::npos) {
        return false;
    }
    std::size_t pos = key_pos + key.size();
    if (pos + 2 <= message.size() && message[pos] == '0' &&
        (message[pos + 1] == 'x' || message[pos + 1] == 'X')) {
        pos += 2;
    }
    std::uint64_t value = 0;
    bool any = false;
    while (pos < message.size()) {
        const char ch = message[pos];
        std::uint8_t digit = 0;
        if (ch >= '0' && ch <= '9') {
            digit = static_cast<std::uint8_t>(ch - '0');
        } else if (ch >= 'a' && ch <= 'f') {
            digit = static_cast<std::uint8_t>(ch - 'a' + 10);
        } else if (ch >= 'A' && ch <= 'F') {
            digit = static_cast<std::uint8_t>(ch - 'A' + 10);
        } else {
            break;
        }
        value = (value << 4) | digit;
        any = true;
        ++pos;
    }
    if (!any) {
        return false;
    }
    out = value;
    return true;
}

std::string NearestGuestSymbolName(const Core::Module& module, const std::uint64_t address,
                                   std::uint64_t& symbol_offset,
                                   std::uint64_t& symbol_delta) {
    symbol_offset = 0;
    symbol_delta = 0;
    if (!module.dynamic_info.symbol_table || !module.dynamic_info.str_table ||
        module.dynamic_info.symbol_table_total_size == 0) {
        return "";
    }

    const std::uint64_t module_base = ModuleBaseAddress(module);
    if (module_base == 0 || address < module_base) {
        return "";
    }

    const std::uint64_t module_offset = address - module_base;
    const auto* begin = module.dynamic_info.symbol_table;
    const auto* end = reinterpret_cast<const elf_symbol*>(
        reinterpret_cast<const std::uint8_t*>(module.dynamic_info.symbol_table) +
        module.dynamic_info.symbol_table_total_size);

    const elf_symbol* best = nullptr;
    std::uint64_t best_delta = ~std::uint64_t{0};
    for (const elf_symbol* sym = begin; sym < end; ++sym) {
        if (sym->st_value == 0 || sym->st_name >= module.dynamic_info.str_table_size) {
            continue;
        }
        const std::uint8_t type = sym->GetType();
        if (type != STT_FUN && type != STT_OBJECT && type != STT_NOTYPE && type != STT_SCE) {
            continue;
        }
        if (sym->st_value > module_offset) {
            continue;
        }
        const std::uint64_t delta = module_offset - sym->st_value;
        if (delta < best_delta) {
            best_delta = delta;
            best = sym;
        }
    }

    if (!best) {
        return "";
    }
    symbol_offset = best->st_value;
    symbol_delta = best_delta;
    const char* raw_name = module.dynamic_info.str_table + best->st_name;
    return raw_name ? std::string(raw_name) : "";
}

extern "C" __attribute__((visibility("default"))) int executor_lsx4_android_symbolize_guest_pc(
    std::uint64_t pc, char* module_name, std::size_t module_name_size, std::uint64_t* module_base,
    std::uint64_t* module_offset, char* symbol_name, std::size_t symbol_name_size,
    std::uint64_t* symbol_offset, std::uint64_t* symbol_delta) {
    auto write_cstr = [](char* dst, std::size_t dst_size, const std::string& src) {
        if (!dst || dst_size == 0) {
            return;
        }
        const std::size_t n = std::min(dst_size - 1, src.size());
        std::memcpy(dst, src.data(), n);
        dst[n] = '\0';
    };

    if (module_base) {
        *module_base = 0;
    }
    if (module_offset) {
        *module_offset = 0;
    }
    if (symbol_offset) {
        *symbol_offset = 0;
    }
    if (symbol_delta) {
        *symbol_delta = 0;
    }
    if (module_name && module_name_size > 0) {
        module_name[0] = '\0';
    }
    if (symbol_name && symbol_name_size > 0) {
        symbol_name[0] = '\0';
    }

    Core::Module* module = FindGuestModuleByAddress(pc);
    if (!module) {
        return 0;
    }

    const std::uint64_t base = ModuleBaseAddress(*module);
    const std::uint64_t offset = GuestModuleOffset(*module, pc);
    if (module_base) {
        *module_base = base;
    }
    if (module_offset) {
        *module_offset = offset;
    }
    write_cstr(module_name, module_name_size, module->file.filename().string());

    std::uint64_t nearest_offset = 0;
    std::uint64_t nearest_delta = 0;
    const std::string nearest = NearestGuestSymbolName(*module, pc, nearest_offset, nearest_delta);
    if (symbol_offset) {
        *symbol_offset = nearest_offset;
    }
    if (symbol_delta) {
        *symbol_delta = nearest_delta;
    }
    write_cstr(symbol_name, symbol_name_size, nearest);
    return 1;
}

std::string ClassifyMappedEntryAddress(const ExecutorBox64MappedEntryRequest& request,
                                       const std::uint64_t address) {
    if (address == 0) {
        return "null";
    }
    if (request.exit_func != 0 && address >= request.exit_func &&
        address < request.exit_func + 8) {
        return "exit_func";
    }
    if (request.hle_trampoline_base != 0 && request.hle_trampoline_size != 0 &&
        address >= request.hle_trampoline_base &&
        address < request.hle_trampoline_base + request.hle_trampoline_size) {
        return "hle_trampoline";
    }
    if (request.stack_base != 0 && request.stack_size != 0 &&
        address >= request.stack_base && address < request.stack_base + request.stack_size) {
        return "stack";
    }
    if (FindGuestModuleByAddress(address) != nullptr) {
        return "guest_module";
    }
    return "unknown";
}

bool IsCurrentMappedEntryReadableAddressLocked(const std::uint64_t address) {
    if (address == 0) {
        return false;
    }
    if (g_box64_boundary_probe.stack_base != 0 && g_box64_boundary_probe.stack_size != 0 &&
        address >= g_box64_boundary_probe.stack_base &&
        address < g_box64_boundary_probe.stack_base + g_box64_boundary_probe.stack_size) {
        return true;
    }
    {
        std::lock_guard stack_lock(g_box64_guest_stack_lock);
        for (const auto& range : g_box64_guest_readable_ranges) {
            if (range.base != 0 && range.size != 0 && address >= range.base &&
                address < range.base + range.size) {
                return true;
            }
        }
    }
    if (FindGuestModuleByAddress(address) != nullptr) {
        return true;
    }
    auto* memory = Core::Memory::Instance();
    return memory != nullptr && memory->IsValidMapping(address, 1);
}

bool IsHostAddressReadableByProcMaps(const std::uint64_t address) {
    if (address == 0) {
        return false;
    }
#if defined(__ANDROID__) || defined(__linux__)
    constexpr std::uint64_t PageMask = ~0xfffull;
    const std::uint64_t page = address & PageMask;
    static std::mutex maps_cache_mutex;
    static std::unordered_map<std::uint64_t, bool> maps_cache;
    {
        std::lock_guard lock(maps_cache_mutex);
        if (const auto it = maps_cache.find(page); it != maps_cache.end()) {
            return it->second;
        }
    }

    bool readable = false;
    std::ifstream maps("/proc/self/maps");
    std::string line;
    while (std::getline(maps, line)) {
        unsigned long long begin = 0;
        unsigned long long end = 0;
        char perms[8] = {};
        if (std::sscanf(line.c_str(), "%llx-%llx %7s", &begin, &end, perms) != 3) {
            continue;
        }
        if (address >= begin && address < end) {
            readable = perms[0] == 'r';
            break;
        }
    }

    {
        std::lock_guard lock(maps_cache_mutex);
        if (maps_cache.size() > 32768) {
            maps_cache.clear();
        }
        maps_cache.emplace(page, readable);
    }
    return readable;
#else
    return true;
#endif
}

bool IsHostAddressWritableByProcMaps(const std::uint64_t address) {
    if (address == 0) {
        return false;
    }
#if defined(__ANDROID__) || defined(__linux__)
    constexpr std::uint64_t PageMask = ~0xfffull;
    const std::uint64_t page = address & PageMask;
    static std::mutex maps_cache_mutex;
    static std::unordered_map<std::uint64_t, bool> maps_cache;
    {
        std::lock_guard lock(maps_cache_mutex);
        if (const auto it = maps_cache.find(page); it != maps_cache.end()) {
            return it->second;
        }
    }

    bool writable = false;
    std::ifstream maps("/proc/self/maps");
    std::string line;
    while (std::getline(maps, line)) {
        unsigned long long begin = 0;
        unsigned long long end = 0;
        char perms[8] = {};
        if (std::sscanf(line.c_str(), "%llx-%llx %7s", &begin, &end, perms) != 3) {
            continue;
        }
        if (address >= begin && address < end) {
            writable = perms[1] == 'w';
            break;
        }
    }

    {
        std::lock_guard lock(maps_cache_mutex);
        if (maps_cache.size() > 32768) {
            maps_cache.clear();
        }
        maps_cache.emplace(page, writable);
    }
    return writable;
#else
    return true;
#endif
}

bool IsHostAddressExecutableByProcMaps(const std::uint64_t address) {
    if (address == 0) {
        return false;
    }
    // Fast numeric prefilter for Android shared-library/function pointers. Guest VAs in this
    // runtime are mostly 0x2..., 0x6..., 0x7..., 0x8... (nine hex digits) while host text lives in
    // the high userspace mapping band. Avoid reparsing /proc/self/maps for every arbitrary qword
    // encountered while scanning guest RW segments for HLE imports.
    if (address < 0x1000000000ull || address >= 0x0000800000000000ull) {
        return false;
    }
#if defined(__ANDROID__) || defined(__linux__)
    struct HostExecRange {
        std::uint64_t begin = 0;
        std::uint64_t end = 0;
    };
    static std::mutex maps_cache_mutex;
    static std::vector<HostExecRange> exec_ranges;
    static std::uint64_t miss_count = 0;

    const auto reload_ranges_locked = [&]() {
        exec_ranges.clear();
        std::ifstream maps("/proc/self/maps");
        std::string line;
        while (std::getline(maps, line)) {
            unsigned long long begin = 0;
            unsigned long long end = 0;
            char perms[8] = {};
            if (std::sscanf(line.c_str(), "%llx-%llx %7s", &begin, &end, perms) != 3) {
                continue;
            }
            if (perms[0] == 'r' && perms[2] == 'x') {
                exec_ranges.push_back(
                    HostExecRange{static_cast<std::uint64_t>(begin),
                                  static_cast<std::uint64_t>(end)});
            }
        }
    };
    const auto contains_locked = [&]() {
        for (const HostExecRange& range : exec_ranges) {
            if (address >= range.begin && address < range.end) {
                return true;
            }
        }
        return false;
    };

    std::lock_guard lock(maps_cache_mutex);
    if (exec_ranges.empty()) {
        reload_ranges_locked();
    }
    if (contains_locked()) {
        return true;
    }
    // Native code can be mmap'ed after the first cache fill. Refresh rarely on misses without
    // turning a guest data scan into O(slots * /proc/self/maps).
    if ((++miss_count & 0xffu) == 0) {
        reload_ranges_locked();
        if (contains_locked()) {
            return true;
        }
    }
    return false;
#else
    return true;
#endif
}

std::string ClassifyGuestAddressLocked(const std::uint64_t address) {
    if (address == 0) {
        return "null";
    }
    if (FindGuestModuleByAddress(address) != nullptr) {
        return "guest_module";
    }
    if (g_box64_boundary_probe.stack_base != 0 && g_box64_boundary_probe.stack_size != 0 &&
        address >= g_box64_boundary_probe.stack_base &&
        address < g_box64_boundary_probe.stack_base + g_box64_boundary_probe.stack_size) {
        return "guest_stack";
    }
    {
        std::lock_guard stack_lock(g_box64_guest_stack_lock);
        for (const auto& range : g_box64_guest_readable_ranges) {
            if (range.base != 0 && range.size != 0 && address >= range.base &&
                address < range.base + range.size) {
                return "guest_readable_range";
            }
        }
    }
    auto* memory = Core::Memory::Instance();
    if (memory != nullptr && memory->IsValidMapping(address, 1)) {
        return "core_memory";
    }
    return "unknown";
}

bool GuestReadByteCheckedLocked(const std::uint64_t address, std::uint8_t& out) {
    if (address == 0) {
        return false;
    }
    if (IsCurrentMappedEntryReadableAddressLocked(address) &&
        IsHostAddressReadableByProcMaps(address)) {
        out = *reinterpret_cast<const std::uint8_t*>(address);
        return true;
    }
    // Diagnostic stack/string scanners run on speculative guest addresses. CopySparseMemory is not a
    // try-read API: it asserts on unmapped addresses and can turn logging into SIGTRAP. Keep this path
    // side-effect-free; production libc reads use the guarded stubs in core/aerolib/stubs.cpp.
    return false;
}

bool GuestReadQwordCheckedLocked(const std::uint64_t address, std::uint64_t& out) {
    out = 0;
    std::array<std::uint8_t, sizeof(out)> bytes{};
    for (std::size_t i = 0; i < bytes.size(); ++i) {
        if (!GuestReadByteCheckedLocked(address + i, bytes[i])) {
            return false;
        }
    }
    std::memcpy(&out, bytes.data(), sizeof(out));
    return true;
}

std::uint64_t JitCanonicalHostPointer(const std::uint64_t address) {
#if defined(__ANDROID__) && defined(__aarch64__)
    // Android's tagged-address ABI permits a non-zero top byte on heap and
    // alternate-signal-stack pointers. /proc/self/maps contains canonical
    // addresses, so JIT must remove the tag for validation and memcpy.
    // Ordinary PS4 guest VAs are below bit 40 and are therefore unchanged.
    return address & 0x00ffffffffffffffull;
#else
    return address;
#endif
}

bool JitRangeContained(const std::uint64_t address, const std::size_t size,
                            const std::uint64_t range_base, const std::uint64_t range_size) {
    return size != 0 && range_base != 0 && range_size != 0 && address >= range_base &&
           static_cast<std::uint64_t>(size) <= range_size &&
           address - range_base <= range_size - static_cast<std::uint64_t>(size);
}

bool IsJitRegisteredGuestRange(const std::uint64_t address, const std::size_t size) {
    if (IsJitRegisteredPageCached(address, size)) {
        return true;
    }
    if (JitRangeContained(address, size, g_box64_boundary_probe.stack_base,
                               g_box64_boundary_probe.stack_size)) {
        return true;
    }
    std::lock_guard stack_lock(g_box64_guest_stack_lock);
    return std::any_of(g_box64_guest_readable_ranges.begin(),
                       g_box64_guest_readable_ranges.end(),
                       [&](const ExecutorGuestReadableRange& range) {
                           return JitRangeContained(address, size, range.base, range.size);
                       });
}

bool IsJitOrdinaryGuestRange(const std::uint64_t address, const std::size_t size) {
    // PS4 CPU/GPU virtual addresses are 40-bit. Keeping this numeric gate in front of the memory
    // manager prevents a tagged/high Android host pointer from ever being mistaken for guest memory.
    constexpr std::uint64_t GuestAddressLimit = 0x10000000000ull;
    if (size == 0 || address < 0x10000ull || address >= GuestAddressLimit ||
        static_cast<std::uint64_t>(size) > GuestAddressLimit - address) {
        return false;
    }
    auto* memory = Core::Memory::Instance();
    if (memory == nullptr) {
        return false;
    }

    // IsValidMapping walks the VMA std::map. Reference-helper loads and stores call this path for
    // every guest operand, even though the set of usable address-space regions is fixed for the
    // lifetime of the process MemoryManager (map/unmap only carve and merge VMAs inside those
    // regions). Cache successful whole-page validations so the common 1/2/4/8/16-byte operand path
    // is one relaxed atomic load instead of an ordered-map lookup. This deliberately is not
    // thread_local: Android resolves function-local TLS in this dlopened library through
    // tlsdesc_resolver_dynamic, which profiling showed consuming 10% of Game:Main after the VMA
    // lookup itself had fallen to 1.2%. The validated property is process-global, and the
    // MemoryManager singleton is not replaced during a process lifetime, so a shared lock-free
    // direct map is the exact contract and avoids that resolver entirely. Validating the complete
    // page on a miss keeps boundary/gap behavior byte-exact; cross-page operands retain the
    // authoritative slow path below.
    constexpr std::uint64_t GuestValidationPageSize = 64_KB;
    constexpr std::uint64_t GuestValidationPageMask = GuestValidationPageSize - 1;
    constexpr std::size_t GuestValidationCacheSlots = 256;
    static_assert((GuestValidationPageSize & GuestValidationPageMask) == 0);
    static_assert((GuestValidationCacheSlots & (GuestValidationCacheSlots - 1)) == 0);
    static std::array<std::atomic<std::uint64_t>, GuestValidationCacheSlots> cache{};

    const std::uint64_t page_base = address & ~GuestValidationPageMask;
    const std::uint64_t offset = address - page_base;
    if (static_cast<std::uint64_t>(size) <= GuestValidationPageSize - offset) {
        auto& entry = cache[(page_base >> 16u) & (GuestValidationCacheSlots - 1)];
        if (entry.load(std::memory_order_relaxed) == page_base) {
            return true;
        }
        if (memory->IsValidMapping(page_base, GuestValidationPageSize)) {
            entry.store(page_base, std::memory_order_relaxed);
            return true;
        }
    }
    return memory->IsValidMapping(address, size);
}

bool IsJitCurrentThreadStackRange(const std::uint64_t address, const std::size_t size) {
#if defined(__ANDROID__)
    struct HostStackRange {
        std::uint64_t base = 0;
        std::uint64_t size = 0;
    };
    // Interpreter stores (including REP MOVS/STOS lanes) normally pass a small buffer from the
    // current C++ stack. Discover that stack once per host thread instead of serializing every store
    // on the process-maps cache mutex. Unknown/high heap and self-test buffers retain the maps fallback.
    thread_local const HostStackRange stack = [] {
        pthread_attr_t attr{};
        if (pthread_getattr_np(pthread_self(), &attr) != 0) {
            return HostStackRange{};
        }
        void* base = nullptr;
        std::size_t size = 0;
        const int result = pthread_attr_getstack(&attr, &base, &size);
        pthread_attr_destroy(&attr);
        if (result != 0 || base == nullptr || size == 0) {
            return HostStackRange{};
        }
        return HostStackRange{JitCanonicalHostPointer(
                                  reinterpret_cast<std::uint64_t>(base)),
                              static_cast<std::uint64_t>(size)};
    }();
    return JitRangeContained(address, size, stack.base, stack.size);
#else
    (void)address;
    (void)size;
    return false;
#endif
}

bool IsJitGuestRangeWithoutProcMaps(const std::uint64_t address, const std::size_t size) {
    // Registered pthread/fallback stacks live outside Core::MemoryManager.  Check their
    // process-lifetime page publication first so hot reference-validation operands do not pay an
    // expected VMA miss before reaching the range which actually owns them.
    return IsJitRegisteredPageCached(address, size) ||
           IsJitOrdinaryGuestRange(address, size) ||
           IsJitRegisteredGuestRange(address, size);
}

bool IsJitSourceRangeWithoutProcMaps(const std::uint64_t address, const std::size_t size) {
    return IsJitCurrentThreadStackRange(address, size) ||
           IsJitGuestRangeWithoutProcMaps(address, size);
}

extern "C" bool ExecutorJitIsReadableGuestRange(const std::uint64_t address,
                                                       const std::size_t size) {
    // This is a pointer-free proof API for HLE consumers that need a direct span rather than a
    // copied buffer.  Canonicalize Android top-byte tags once, reject wraparound, then consult the
    // same authoritative sources as JIT's byte reader: the current native source stack,
    // ordinary identity-mapped guest VMAs, and explicitly registered guest/stack ranges.  Do not
    // fall back to arbitrary /proc/self/maps entries here: a readable low fixed host mmap is not by
    // itself proof that the address is guest-owned.
    if (address == 0 || size == 0) {
        return false;
    }
    const std::uint64_t host_address = JitCanonicalHostPointer(address);
    if (host_address == 0 ||
        static_cast<std::uint64_t>(size - 1) > ~std::uint64_t{0} - host_address) {
        return false;
    }
    return IsJitSourceRangeWithoutProcMaps(host_address, size);
}

extern "C" bool ExecutorJitReadGuestBytes(const std::uint64_t address, void* dst,
                                               const std::size_t size) {
    if (size == 0) {
        return true;
    }
    if (address == 0 || dst == nullptr || address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    const std::uint64_t host_address = JitCanonicalHostPointer(address);
    const std::uint64_t host_dst =
        JitCanonicalHostPointer(reinterpret_cast<std::uint64_t>(dst));
    if (host_address == 0 || host_dst == 0 ||
        host_address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    // Ordinary guest mappings and registered guest stacks are already authoritative. Avoid the
    // process-global /proc/self/maps cache mutex on every interpreted/JIT memory operand.
    if (IsJitGuestRangeWithoutProcMaps(host_address, size)) {
        std::memcpy(reinterpret_cast<void*>(host_dst),
                    reinterpret_cast<const void*>(host_address), size);
        return true;
    }
    // JIT also decodes high host self-test buffers before the guest Linker/MemoryManager is
    // initialized. Keep the guarded host fallback for those buffers only.
    if (IsHostAddressReadableByProcMaps(host_address) &&
        IsHostAddressReadableByProcMaps(host_address + size - 1)) {
        std::memcpy(reinterpret_cast<void*>(host_dst),
                    reinterpret_cast<const void*>(host_address), size);
        return true;
    }
    auto* out = static_cast<std::uint8_t*>(dst);
    for (std::size_t i = 0; i < size; ++i) {
        if (!GuestReadByteCheckedLocked(address + i, out[i])) {
            return false;
        }
    }
    return true;
}

extern "C" bool ExecutorJitReadGuestBytesStable(const std::uint64_t address, void* dst,
                                                     const std::size_t size) {
    if (size == 0) {
        return true;
    }
    if (address == 0 || dst == nullptr || address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    const std::uint64_t host_address = JitCanonicalHostPointer(address);
    if (host_address == 0 ||
        host_address > (~std::uint64_t{0} - (size - 1)) ||
        !IsJitGuestRangeWithoutProcMaps(host_address, size)) {
        return false;
    }
#if (defined(__ANDROID__) || defined(__linux__)) && defined(SYS_process_vm_readv)
    iovec local{
        .iov_base = dst,
        .iov_len = size,
    };
    iovec remote{
        .iov_base = reinterpret_cast<void*>(host_address),
        .iov_len = size,
    };
    // Unlike a validate-then-memcpy sequence, process_vm_readv performs the copy while the kernel
    // owns the remote-mm lookup. If another guest thread unmaps a module concurrently, the read
    // fails with a short result/EFAULT instead of taking SIGBUS between validation and memcpy.
    const long copied =
        syscall(SYS_process_vm_readv, getpid(), &local, 1, &remote, 1, 0);
    return copied == static_cast<long>(size);
#else
    return ExecutorJitReadGuestBytes(address, dst, size);
#endif
}

// Range [lo,hi) of our own loaded host image (liblsx4_executor_android.so). A guest store must
// never land inside a loaded HOST shared object — that only happens when a native JIT block
// computes a store base from a garbage/host pointer (observed: the RSDK audio worker Thread2 stores
// into our .so BSS, corrupting a std::mutex / unordered_map and later FORTIFY-aborting or SIGSEGVing
// a different thread with a shape-shifting victim address). Computed once from /proc/self/maps.
static bool ExecutorOwnHostImageRange(std::uint64_t& lo, std::uint64_t& hi) {
#if defined(__ANDROID__) || defined(__linux__)
    static std::uint64_t s_lo = 0;
    static std::uint64_t s_hi = 0;
    static std::once_flag s_once;
    std::call_once(s_once, [] {
        // Robust: find the /proc/self/maps entry that CONTAINS the address of this very function
        // (guaranteed inside our loaded image), take its pathname, then union every mapping with that
        // same pathname. Avoids relying on dladdr's dli_fname string matching the maps pathname.
        const std::uint64_t self_addr =
            reinterpret_cast<std::uint64_t>(&ExecutorOwnHostImageRange);
        std::ifstream maps("/proc/self/maps");
        std::string line;
        std::string self_path;
        while (std::getline(maps, line)) {
            unsigned long long begin = 0;
            unsigned long long end = 0;
            char perms[8] = {};
            int path_off = 0;
            if (std::sscanf(line.c_str(), "%llx-%llx %7s %*x %*x:%*x %*u %n", &begin, &end, perms,
                            &path_off) < 3) {
                continue;
            }
            if (self_addr >= begin && self_addr < end && path_off > 0 &&
                static_cast<std::size_t>(path_off) < line.size()) {
                self_path = line.substr(static_cast<std::size_t>(path_off));
                while (!self_path.empty() && (self_path.back() == '\n' || self_path.back() == ' ')) {
                    self_path.pop_back();
                }
                break;
            }
        }
        if (self_path.empty()) {
            NativeLog(ANDROID_LOG_ERROR,
                      "[EXECUTOR_OWN_HOST_IMAGE_RANGE] FAILED to find self mapping for addr=0x%llx",
                      static_cast<unsigned long long>(self_addr));
            return;
        }
        std::ifstream maps2("/proc/self/maps");
        std::uint64_t min_begin = ~std::uint64_t{0};
        std::uint64_t max_end = 0;
        while (std::getline(maps2, line)) {
            if (line.find(self_path) == std::string::npos) {
                continue;
            }
            unsigned long long begin = 0;
            unsigned long long end = 0;
            if (std::sscanf(line.c_str(), "%llx-%llx", &begin, &end) != 2) {
                continue;
            }
            min_begin = std::min<std::uint64_t>(min_begin, begin);
            max_end = std::max<std::uint64_t>(max_end, end);
        }
        if (max_end > min_begin) {
            s_lo = min_begin;
            s_hi = max_end;
        }
        NativeLog(ANDROID_LOG_ERROR,
                  "[EXECUTOR_OWN_HOST_IMAGE_RANGE] path=%s lo=0x%llx hi=0x%llx",
                  self_path.c_str(), static_cast<unsigned long long>(s_lo),
                  static_cast<unsigned long long>(s_hi));
    });
    lo = s_lo;
    hi = s_hi;
    return s_hi > s_lo;
#else
    (void)lo;
    (void)hi;
    return false;
#endif
}

extern "C" bool ExecutorJitWriteGuestBytes(const std::uint64_t address, const void* src,
                                                const std::size_t size) {
    if (size == 0) {
        return true;
    }
    if (address == 0 || src == nullptr || address > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    const std::uint64_t host_address = JitCanonicalHostPointer(address);
    const std::uint64_t host_src =
        JitCanonicalHostPointer(reinterpret_cast<std::uint64_t>(src));
    if (host_address == 0 || host_src == 0 ||
        host_address > (~std::uint64_t{0} - (size - 1)) ||
        host_src > (~std::uint64_t{0} - (size - 1))) {
        return false;
    }
    if (std::uint64_t img_lo = 0, img_hi = 0; ExecutorOwnHostImageRange(img_lo, img_hi) &&
                                              host_address < img_hi &&
                                              (host_address + size) > img_lo) {
        static std::atomic<std::uint32_t> s_budget{0};
        const std::uint32_t n = s_budget.fetch_add(1, std::memory_order_relaxed);
        if (n < 64) {
            NativeLog(ANDROID_LOG_ERROR,
                      "[EXECUTOR_GUEST_STORE_INTO_HOST_IMAGE] n=%u dst=0x%llx size=%zu "
                      "image=[0x%llx,0x%llx) (rejected; JIT garbage store base)",
                      n, static_cast<unsigned long long>(address), size,
                      static_cast<unsigned long long>(img_lo),
                      static_cast<unsigned long long>(img_hi));
            std::FILE* cf = std::fopen(
                "/data/data/app.lsx4.android/files/lsx4-home/jit-checkfail.txt", "a");
            if (cf != nullptr) {
                std::fprintf(cf, "GUEST_STORE_INTO_HOST_IMAGE dst=0x%llx size=%zu\n",
                             static_cast<unsigned long long>(address), size);
                std::fclose(cf);
            }
        }
        return false;
    }
    // The memcpy below READS `src` — for a guest string/block store (rep movs) `src` is itself a
    // guest address, and the RSDK audio worker (Thread2) reaches here with a near-null source
    // (0x4b0 etc) that is unmapped, so the memcpy SIGSEGVs reading src and takes the whole process
    // down. Validate the SOURCE range too (not just the writable destination) and skip the copy on
    // a bad read, exactly as a real guest fault would (the offending guest thread continues instead
    // of crashing every other thread). Guards the null-page and any unmapped source page.
    if (host_src < 0x10000ull) {
        return false;
    }
    const bool destination_is_guest =
        IsJitGuestRangeWithoutProcMaps(host_address, size);
    if (!destination_is_guest) {
        const bool destination_writable =
            IsHostAddressWritableByProcMaps(host_address) &&
            IsHostAddressWritableByProcMaps(host_address + size - 1);
        const bool destination_readable =
            IsHostAddressReadableByProcMaps(host_address) &&
            IsHostAddressReadableByProcMaps(host_address + size - 1);
        if (!destination_writable && !destination_readable) {
            return false;
        }
    }
    if (!IsJitSourceRangeWithoutProcMaps(host_src, size) &&
        (!IsHostAddressReadableByProcMaps(host_src) ||
         !IsHostAddressReadableByProcMaps(host_src + size - 1))) {
        return false;
    }
    // PageManager intentionally write-protects GPU-observed guest pages. If this store reaches a
    // watched page, Linux supplies ESR_ELx.WnR in the AArch64 signal context; the shared reference
    // signal path invalidates/unprotects the page and resumes this instruction.
    std::memcpy(reinterpret_cast<void*>(host_address), reinterpret_cast<const void*>(host_src),
                size);
    return true;
}

bool GuestReadQwordDirectMspaceLocked(const std::uint64_t address, std::uint64_t& out) {
    out = 0;
#if defined(__ANDROID__)
    constexpr std::uint64_t kMspaceLo = Core::EXECUTOR_LIBC_MSPACE_BASE;
    constexpr std::uint64_t kMspaceHi =
        Core::EXECUTOR_LIBC_MSPACE_BASE + Core::EXECUTOR_LIBC_MSPACE_CAPACITY;
    if (address < kMspaceLo || address + sizeof(out) > kMspaceHi || address + sizeof(out) < address) {
        return false;
    }
    out = *reinterpret_cast<const volatile std::uint64_t*>(address);
    return true;
#else
    (void)address;
    return false;
#endif
}

bool GuestReadQwordBestEffortLocked(const std::uint64_t address, std::uint64_t& out) {
    if (GuestReadQwordDirectMspaceLocked(address, out)) {
        return true;
    }
    return GuestReadQwordCheckedLocked(address, out);
}

bool GuestWriteQwordBestEffortLocked(const std::uint64_t address, const std::uint64_t value) {
#if defined(__ANDROID__)
    constexpr std::uint64_t kMspaceLo = Core::EXECUTOR_LIBC_MSPACE_BASE;
    constexpr std::uint64_t kMspaceHi =
        Core::EXECUTOR_LIBC_MSPACE_BASE + Core::EXECUTOR_LIBC_MSPACE_CAPACITY;
    if (address >= kMspaceLo && address + sizeof(value) <= kMspaceHi &&
        address + sizeof(value) >= address) {
        *reinterpret_cast<volatile std::uint64_t*>(address) = value;
        return true;
    }
#endif
    auto* memory = Core::Memory::Instance();
    if (address == 0 || memory == nullptr || !memory->IsValidMapping(address, sizeof(value))) {
        return false;
    }
    return memory->TryWriteBacking(reinterpret_cast<void*>(address), &value, sizeof(value));
}

std::string GuestBytesHexBestEffortLocked(const std::uint64_t address, const std::size_t size) {
    if (!address || size == 0) {
        return "";
    }
    std::ostringstream out;
    for (std::size_t i = 0; i < size; ++i) {
        if (i != 0) {
            out << ' ';
        }
        std::uint8_t byte = 0;
        bool have = false;
#if defined(__ANDROID__)
        constexpr std::uint64_t kMspaceLo = Core::EXECUTOR_LIBC_MSPACE_BASE;
        constexpr std::uint64_t kMspaceHi =
            Core::EXECUTOR_LIBC_MSPACE_BASE + Core::EXECUTOR_LIBC_MSPACE_CAPACITY;
        const std::uint64_t ai = address + i;
        if (ai >= kMspaceLo && ai < kMspaceHi && ai >= address) {
            byte = *reinterpret_cast<const volatile std::uint8_t*>(ai);
            have = true;
        }
#endif
        if (!have) {
            have = GuestReadByteCheckedLocked(address + i, byte);
        }
        if (!have) {
            out << "??";
            continue;
        }
        static constexpr char Hex[] = "0123456789abcdef";
        out << Hex[(byte >> 4) & 0xf] << Hex[byte & 0xf];
    }
    return out.str();
}

std::string GuestQwordsHexBestEffortLocked(const std::uint64_t address, const std::size_t qword_count) {
    if (!address || qword_count == 0) {
        return "";
    }
    std::ostringstream out;
    for (std::size_t i = 0; i < qword_count; ++i) {
        if (i != 0) {
            out << ' ';
        }
        std::uint64_t value = 0;
        if (!GuestReadQwordBestEffortLocked(address + i * sizeof(value), value)) {
            out << "????????????????";
            continue;
        }
        out << std::hex;
        out.width(16);
        out.fill('0');
        out << value;
    }
    return out.str();
}

void RegisterBox64GuestReadableRange(const void* base, const std::size_t size,
                                     const char* label) {
    const auto address = reinterpret_cast<std::uint64_t>(base);
    if (address == 0 || size == 0) {
        return;
    }
    bool added = false;
    {
        std::lock_guard stack_lock(g_box64_guest_stack_lock);
        const auto exists = std::any_of(
            g_box64_guest_readable_ranges.begin(), g_box64_guest_readable_ranges.end(),
            [&](const ExecutorGuestReadableRange& range) {
                return range.base == address && range.size == size;
            });
        if (!exists) {
            g_box64_guest_readable_ranges.push_back(
                ExecutorGuestReadableRange{address, static_cast<std::uint64_t>(size),
                                           label ? label : "guest_range"});
            added = true;
        }
    }
    PublishJitRegisteredFullPages(address, size);
    static std::atomic_uint32_t readable_range_log_count{0};
    if (added && readable_range_log_count.fetch_add(1, std::memory_order_relaxed) < 4) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_GUEST_READABLE_RANGE] base=%p size=0x%zx label=%s",
                  base, size, label ? label : "guest_range");
    }
}

void RegisterBox64GuestStackRange(const void* base, const std::size_t size,
                                   const char* label) {
    const auto address = reinterpret_cast<std::uint64_t>(base);
    if (address == 0 || size == 0) {
        return;
    }
    bool added = false;
    {
        std::lock_guard stack_lock(g_box64_guest_stack_lock);
        const auto exists = std::any_of(
            g_box64_guest_stack_ranges.begin(), g_box64_guest_stack_ranges.end(),
            [&](const ExecutorGuestReadableRange& range) {
                return range.base == address && range.size == size;
            });
        if (!exists) {
            g_box64_guest_stacks.push_back(const_cast<void*>(base));
            g_box64_guest_stack_ranges.push_back(
                ExecutorGuestReadableRange{address, static_cast<std::uint64_t>(size),
                                           label ? label : "guest_stack"});
            added = true;
        }
    }
    if (added) {
        MarkBox64GuestGcRootsDirty();
    }
    RegisterBox64GuestReadableRange(base, size, label ? label : "guest_stack");
}

void RegisterBox64GuestGcSidebandRange(const void* base, const std::size_t size,
                                        const char* label) {
    const auto address = reinterpret_cast<std::uint64_t>(base);
    if (address == 0 || size == 0) {
        return;
    }
    bool added = false;
    {
        std::lock_guard stack_lock(g_box64_guest_stack_lock);
        const auto exists = std::any_of(
            g_box64_guest_gc_sideband_ranges.begin(), g_box64_guest_gc_sideband_ranges.end(),
            [&](const ExecutorGuestReadableRange& range) {
                return range.base == address && range.size == size;
            });
        if (!exists) {
            g_box64_guest_gc_sideband_ranges.push_back(
                ExecutorGuestReadableRange{address, static_cast<std::uint64_t>(size),
                                           label ? label : "guest_gc_sideband"});
            added = true;
        }
    }
    if (added) {
        MarkBox64GuestGcRootsDirty();
    }
}

