extern "C" int executor_lsx4_runtime_present_linear_image(const std::uint64_t source_address,
                                                             const std::uint32_t width,
                                                             const std::uint32_t height,
                                                             const std::uint32_t stride_bytes,
                                                             const std::uint32_t) {
    std::lock_guard lock(g_lock);
    return PresentRgba8888Linear(reinterpret_cast<const void*>(static_cast<std::uintptr_t>(source_address)),
                                 width, height, stride_bytes);
}

extern "C" int executor_lsx4_runtime_present_test_pattern(int width, int height) {
    std::lock_guard lock(g_lock);
    if (width <= 0) {
        width = 640;
    }
    if (height <= 0) {
        height = 360;
    }

    std::vector<std::uint32_t> pixels(static_cast<std::size_t>(width) *
                                     static_cast<std::size_t>(height));
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            const std::uint8_t r =
                static_cast<std::uint8_t>((x * 255) / std::max(1, width - 1));
            const std::uint8_t g =
                static_cast<std::uint8_t>((y * 255) / std::max(1, height - 1));
            const std::uint8_t b = static_cast<std::uint8_t>((x ^ y) & 0xff);
            pixels[static_cast<std::size_t>(y) * width + x] = Rgba(r, g, b);
        }
    }
    return PresentRgba8888Linear(pixels.data(), static_cast<std::uint32_t>(width),
                                 static_cast<std::uint32_t>(height),
                                 static_cast<std::uint32_t>(width) * 4u);
}

extern "C" int executor_lsx4_runtime_present_frame_dump_file(const char* path) {
    std::lock_guard lock(g_lock);
    return PresentFrameDumpFileLocked(path ? path : "");
}

// ---- Present pump ------------------------------------------------------------------------------
// The homebrew helper/service guest writes each flipped frame to translator/executor-videoout-frame.bin
// (libSceVideoOut shim dump_frame). The UI process owns the Surface, so this pump polls that file and
// blits new frames via the existing frame-dump present path. runtime_bridge.cpp resolves
// executor_lsx4_runtime_start/stop_present_pump optionally and, until now, got NULL — helper flips
// (observed 1833/run) never reached the screen. Partial writes are safe: the header/size validation in
// PresentFrameDumpFileLocked rejects a mid-write file (-45) and we retry next tick; the last-presented
// stamp only advances on success.
namespace {
std::atomic<bool> g_present_pump_run{false};
std::thread g_present_pump_thread;
std::mutex g_present_pump_control;
} // namespace

extern "C" int executor_lsx4_runtime_stop_present_pump() {
    std::lock_guard control(g_present_pump_control);
    g_present_pump_run.store(false, std::memory_order_release);
    if (g_present_pump_thread.joinable()) {
        g_present_pump_thread.join();
    }
    NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] stopped");
    return 0;
}

extern "C" int executor_lsx4_runtime_start_present_pump(const char* frame_path, int fps) {
    if (frame_path == nullptr || frame_path[0] == '\0') {
        return -1;
    }
    std::lock_guard control(g_present_pump_control);
    g_present_pump_run.store(false, std::memory_order_release);
    if (g_present_pump_thread.joinable()) {
        g_present_pump_thread.join();
    }
    const std::string path = frame_path;
    const auto interval =
        std::chrono::milliseconds(fps > 0 ? std::max(1, 1000 / fps) : 62);
    g_present_pump_run.store(true, std::memory_order_release);
    g_present_pump_thread = std::thread([path, interval] {
        std::filesystem::file_time_type last_mtime{};
        std::uintmax_t last_size = 0;
        std::uint64_t presented = 0;
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] started path=%s intervalMs=%lld",
                  path.c_str(), static_cast<long long>(interval.count()));
        while (g_present_pump_run.load(std::memory_order_acquire)) {
            std::error_code ec;
            const auto mtime = std::filesystem::last_write_time(path, ec);
            const auto size = ec ? 0 : std::filesystem::file_size(path, ec);
            if (!ec && size >= 64 && (mtime != last_mtime || size != last_size)) {
                const int rc = executor_lsx4_runtime_present_frame_dump_file(path.c_str());
                if (rc == 0) {
                    last_mtime = mtime;
                    last_size = size;
                    ++presented;
                    if (presented <= 8 || (presented & 63u) == 0) {
                        NativeLog(ANDROID_LOG_INFO,
                                  "[EXECUTOR_PRESENT_PUMP] presented=%llu size=%llu",
                                  static_cast<unsigned long long>(presented),
                                  static_cast<unsigned long long>(size));
                    }
                }
            }
            std::this_thread::sleep_for(interval);
        }
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] exit presented=%llu",
                  static_cast<unsigned long long>(presented));
    });
    return 0;
}

