extern "C" int executor_lsx4_runtime_launch_game_jit(const char* path) {
    const int load_result = executor_lsx4_runtime_launch_game(path);
    if (load_result < 0) {
        return load_result;
    }
    const int relocate_result = executor_lsx4_runtime_relocate_imports();
    if (relocate_result < 0) {
        return relocate_result;
    }
    g_jit_launch_entry_requested.store(true, std::memory_order_release);
    return executor_lsx4_runtime_run_jit_mapped_entry();
}

extern "C" int executor_lsx4_runtime_launch_game(const char* path) {
    std::lock_guard lock(g_lock);
    g_runtime_guest_backend.store(1, std::memory_order_release);
    executor_lsx4_install_jit_signal_handlers();
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_RUNTIME_GUEST_BACKEND] launch route=%s",
              RuntimeGuestBackendName());
    const std::string raw_path = path ? path : "";
    if (raw_path.empty()) {
        g_status = R"({"state":"module_load_failed","core":"lsx4-native","error":"empty path"})";
        return -1;
    }

    std::string direct_launch_title;
    if (TryParseDirectTitleLaunch(raw_path, direct_launch_title)) {
        LoadAndroidGameSpecificConfig(direct_launch_title);
        const auto direct_app0 = std::filesystem::path(g_root) / "runtime-fs" / "user" /
                                 "app" / direct_launch_title;
        ConfigureJitPersistentCacheForLaunch(
            true, direct_app0, direct_app0 / "eboot.bin");
        return DirectLaunchInstalledTitleLocked(direct_launch_title);
    }

    const auto launch_path = ResolveLaunchPath(raw_path);
    if (!std::filesystem::exists(launch_path)) {
        g_status = std::string(R"({"state":"module_load_failed","core":"lsx4-native","path":")") +
                   JsonEscape(launch_path.string()) + R"(","error":"path does not exist"})";
        return -2;
    }

    std::string stage = "start";
    try {
        NoteLaunchStageLocked(launch_path, "entered");
        stage = "start_user_session";
        Libraries::UserService::StartUserServiceSession();
        stage = "mount_app0";
        NoteLaunchStageLocked(launch_path, "mount_app0_begin");
        auto* mnt = Common::Singleton<Core::FileSys::MntPoints>::Instance();
        mnt->Unmount(launch_path.parent_path(), "/app0");
        mnt->Unmount(launch_path.parent_path(), "/hostapp");
        mnt->Unmount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/ITEM00001-app0");
        mnt->Unmount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/NPXS39041-app0");
        mnt->Unmount(std::filesystem::path(g_root), "/user/app/NPXS39041");
        mnt->Unmount(std::filesystem::path(g_root), "/user/app");
        mnt->Unmount(std::filesystem::path(g_root), "/user/appmeta/NPXS39041");
        mnt->Unmount(std::filesystem::path(g_root), "/user/appmeta/external/NPXS39041");
        mnt->Unmount(std::filesystem::path(g_root), "/user/appmeta");
        mnt->Unmount(std::filesystem::path(g_root), "/system_ex/app/NPXS20113/bdjstack/lib/fonts");
        mnt->Unmount(std::filesystem::path(g_root), "/data/self");
        mnt->Unmount(std::filesystem::path(g_root), "/data");
        mnt->Unmount(std::filesystem::path(g_root), "/system_data");
        mnt->Unmount(std::filesystem::path(g_root), "/temp0");
        mnt->Unmount(std::filesystem::path(g_root), "/temp");
        mnt->Unmount(std::filesystem::path(g_root), "/download0");
        mnt->Mount(launch_path.parent_path(), "/app0", true);
        mnt->Mount(launch_path.parent_path(), "/hostapp", true);
        mnt->Mount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/ITEM00001-app0", true);
        mnt->Mount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/NPXS39041-app0", true);

        const auto sandbox_fs = std::filesystem::path(g_root) / "runtime-fs";
        const auto staged_app0_path = sandbox_fs / "app0";
        const auto launch_app0_path = launch_path.parent_path();
        const auto launch_app0_eboot = launch_app0_path / "eboot.bin";
        const auto staged_app0_eboot = staged_app0_path / "eboot.bin";
        const auto app0_path = std::filesystem::exists(launch_app0_eboot)
                                   ? launch_app0_path
                                   : (std::filesystem::exists(staged_app0_eboot)
                                          ? staged_app0_path
                                          : launch_app0_path);
        // Choose exactly one allocator owner before Linker/MemoryManager or any HLE symbol table
        // can be constructed.  A bundled Sony libc is the canonical owner; titles without one use
        // the Executor HLE allocator.  Filesystem errors and conflicting late reconfiguration are
        // fatal because silently changing owner would corrupt allocator metadata across every PRX.
        std::error_code libc_probe_error;
        const auto guest_libc_path = app0_path / "sce_module" / "libc.prx";
        const bool has_guest_libc =
            std::filesystem::is_regular_file(guest_libc_path, libc_probe_error);
        if (libc_probe_error) {
            throw std::runtime_error(std::string("failed to probe title libc: ") +
                                     libc_probe_error.message());
        }
        if (!Core::AeroLib::ExecutorConfigureLibcAllocatorOwner(has_guest_libc)) {
            throw std::runtime_error("libc allocator owner was already configured differently");
        }
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_LIBC_ALLOCATOR_POLICY] owner=%s available=%d path=%s",
                  has_guest_libc ? "guest-libc" : "executor-hle", has_guest_libc ? 1 : 0,
                  guest_libc_path.string().c_str());
        ConfigureJitPersistentCacheForLaunch(true, app0_path, launch_path);
        const auto managed_path = app0_path / "Media" / "Managed";
        if (std::filesystem::exists(managed_path)) {
            const std::string mono_path =
                std::string("/app0/Media/Managed:/hostapp/Media/Managed:") +
                managed_path.string();
            setenv("MONO_PATH", mono_path.c_str(), 1);
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_MONO_PATH] source=live_app0 path=%s",
                      mono_path.c_str());
        } else {
            unsetenv("MONO_PATH");
            NativeLog(ANDROID_LOG_WARN, "[EXECUTOR_MONO_PATH] source=live_app0 missing=%s",
                      managed_path.string().c_str());
        }
        const auto user_app_root_path = sandbox_fs / "user" / "app";
        const auto user_app_path = sandbox_fs / "user" / "app" / "NPXS39041";
        const auto itemzflow_user_app_path = sandbox_fs / "user" / "app" / "ITEM00001";
        const auto user_appmeta_root_path = sandbox_fs / "user" / "appmeta";
        const auto user_appmeta_path = sandbox_fs / "user" / "appmeta" / "NPXS39041";
        const auto itemzflow_appmeta_external_path =
            sandbox_fs / "user" / "appmeta" / "external" / "ITEM00001";
        const auto user_appmeta_external_path =
            sandbox_fs / "user" / "appmeta" / "external" / "NPXS39041";
        const auto data_self_path = sandbox_fs / "data" / "self";
        const auto data_path = sandbox_fs / "data";
        const auto system_data_path = sandbox_fs / "system_data";
        const auto temp_path = sandbox_fs / "temp";
        const auto download_path = sandbox_fs / "download0";
        NoteLaunchStageLocked(launch_path, "runtime_fs_prepare_begin",
                              std::string("app0=") + app0_path.string());
        std::filesystem::create_directories(user_app_root_path);
        std::filesystem::create_directories(itemzflow_user_app_path);
        std::filesystem::create_directories(user_app_path / "logs");
        std::filesystem::create_directories(user_app_path / "storedata");
        std::filesystem::create_directories(user_app_path / "downloads");
        std::filesystem::create_directories(user_appmeta_path);
        std::filesystem::create_directories(user_appmeta_root_path / "external");
        std::filesystem::create_directories(itemzflow_appmeta_external_path);
        std::filesystem::create_directories(user_appmeta_external_path);
        std::filesystem::create_directories(data_self_path);
        std::filesystem::create_directories(data_path);
        std::filesystem::create_directories(system_data_path);
        {
            const auto dsdm_path = data_path / "DSDM";
            std::ofstream dsdm(dsdm_path, std::ios::binary | std::ios::trunc);
            dsdm << "executor-android-skip-donate-dialog\n";
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] /data/DSDM marker => %s",
                      dsdm_path.string().c_str());
        }
        std::filesystem::create_directories(temp_path);
        std::filesystem::create_directories(download_path);
        SeedStoreSandbox(app0_path, user_app_path);
        SeedItemzflowSandbox(app0_path, itemzflow_user_app_path, user_appmeta_root_path, data_path,
                             system_data_path);
        const bool has_itemzcore_self = std::filesystem::exists(app0_path / "ItemzCore.self");
        Libraries::Piglet::SetGuestSwapExpected(has_itemzcore_self, "launch_runtime_app0_probe");
        if (has_itemzcore_self) {
            const char* hold_first_frame = std::getenv("EXECUTOR_ITEMZFLOW_HOLD_FIRST_FRAME");
            const bool hold_enabled = hold_first_frame != nullptr && hold_first_frame[0] != '\0' &&
                                      std::strcmp(hold_first_frame, "0") != 0;
            if (hold_enabled) {
                const char* freeze_after_frames =
                    std::getenv("EXECUTOR_PIGLET_FREEZE_AFTER_GUEST_SWAP_FRAMES");
                if (freeze_after_frames == nullptr || freeze_after_frames[0] == '\0') {
                    setenv("EXECUTOR_PIGLET_FREEZE_AFTER_GUEST_SWAP_FRAMES", "2", 1);
                    freeze_after_frames = "2";
                }
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_ITEMZFLOW_RENDER] persistent_render_loop=0 "
                          "freeze_after_guest_swap_frames=%s source=env_hold_first_frame",
                          freeze_after_frames);
            } else {
                const char* auto_present_freeze =
                    std::getenv("EXECUTOR_ITEMZFLOW_FREEZE_AFTER_AUTOPRESENT_FRAMES");
                const bool auto_present_freeze_enabled =
                    auto_present_freeze != nullptr && auto_present_freeze[0] != '\0' &&
                    std::strcmp(auto_present_freeze, "0") != 0;
                if (!auto_present_freeze_enabled) {
                    unsetenv("EXECUTOR_ITEMZFLOW_FREEZE_AFTER_AUTOPRESENT_FRAMES");
                    auto_present_freeze = "0";
                }
                unsetenv("EXECUTOR_PIGLET_FREEZE_AFTER_GUEST_SWAP_FRAMES");
                const char* safety_overlay = std::getenv("EXECUTOR_ITEMZFLOW_SAFETY_OVERLAY");
                const bool safety_overlay_enabled =
                    safety_overlay != nullptr && safety_overlay[0] != '\0' &&
                    std::strcmp(safety_overlay, "0") != 0;
                if (safety_overlay_enabled) {
                    if (std::getenv("EXECUTOR_ITEMZFLOW_FORCE_FALLBACK_OVERLAY") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_FORCE_FALLBACK_OVERLAY", "1", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_AUTOPRESENT_DRAWS") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_AUTOPRESENT_DRAWS", "1", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_PROTECT_TEXTURE_LIFETIME") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_PROTECT_TEXTURE_LIFETIME", "1", 1);
                    }
                    unsetenv("EXECUTOR_ITEMZFLOW_DISABLE_FALLBACK_OVERLAY");
                } else {
                    if (std::getenv("EXECUTOR_ITEMZFLOW_FORCE_FALLBACK_OVERLAY") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_FORCE_FALLBACK_OVERLAY", "0", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_DISABLE_FALLBACK_OVERLAY") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_DISABLE_FALLBACK_OVERLAY", "1", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_REQUIRE_AUTHENTIC_UI") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_REQUIRE_AUTHENTIC_UI", "1", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_AUTOPRESENT_DRAWS") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_AUTOPRESENT_DRAWS", "0", 1);
                    }
                    if (std::getenv("EXECUTOR_ITEMZFLOW_PROTECT_TEXTURE_LIFETIME") == nullptr) {
                        setenv("EXECUTOR_ITEMZFLOW_PROTECT_TEXTURE_LIFETIME", "0", 1);
                    }
                }
                const auto env_enabled = [](const char* name) {
                    const char* value = std::getenv(name);
                    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
                };
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_ITEMZFLOW_RENDER] persistent_render_loop=%d "
                          "freeze_after_guest_swap_frames=0 freeze_after_autopresent_frames=%s "
                          "visual_safety_overlay=%s fallback_disabled=%s "
                          "require_authentic=%s autopresent_draws=%s texture_lifetime_guard=%s "
                          "source=itemzflow_visible_frame_guard",
                          auto_present_freeze_enabled ? 0 : 1,
                          auto_present_freeze,
                          env_enabled("EXECUTOR_ITEMZFLOW_FORCE_FALLBACK_OVERLAY") ? "1" : "0",
                          env_enabled("EXECUTOR_ITEMZFLOW_DISABLE_FALLBACK_OVERLAY") ? "1" : "0",
                          env_enabled("EXECUTOR_ITEMZFLOW_REQUIRE_AUTHENTIC_UI") ? "1" : "0",
                          env_enabled("EXECUTOR_ITEMZFLOW_AUTOPRESENT_DRAWS") ? "1" : "0",
                          env_enabled("EXECUTOR_ITEMZFLOW_PROTECT_TEXTURE_LIFETIME") ? "1" : "0");
            }
        } else {
            unsetenv("EXECUTOR_PIGLET_FREEZE_AFTER_GUEST_SWAP_FRAMES");
            unsetenv("EXECUTOR_ITEMZFLOW_FREEZE_AFTER_AUTOPRESENT_FRAMES");
        }
        const auto app0_icon = app0_path / "sce_sys" / "icon0.png";
        if (std::filesystem::exists(app0_icon)) {
            std::filesystem::copy_file(app0_icon, user_appmeta_path / "icon0.png",
                                       std::filesystem::copy_options::overwrite_existing);
            std::filesystem::copy_file(app0_icon, user_appmeta_external_path / "icon0.png",
                                       std::filesystem::copy_options::overwrite_existing);
            std::filesystem::copy_file(app0_icon, user_appmeta_root_path / "ITEM00001" /
                                                      "icon0.png",
                                       std::filesystem::copy_options::overwrite_existing);
            std::filesystem::copy_file(app0_icon, itemzflow_appmeta_external_path / "icon0.png",
                                       std::filesystem::copy_options::overwrite_existing);
        }
        if (app0_path != launch_path.parent_path()) {
            mnt->Unmount(launch_path.parent_path(), "/app0");
            mnt->Unmount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/ITEM00001-app0");
            mnt->Unmount(launch_path.parent_path(), "/mnt/sandbox/pfsmnt/NPXS39041-app0");
            mnt->Mount(app0_path, "/app0", true);
            mnt->Mount(app0_path, "/mnt/sandbox/pfsmnt/ITEM00001-app0", true);
            mnt->Mount(app0_path, "/mnt/sandbox/pfsmnt/NPXS39041-app0", true);
        }
        mnt->Mount(user_app_path, "/user/app/NPXS39041", false);
        mnt->Mount(user_app_root_path, "/user/app", false);
        mnt->Mount(user_appmeta_path, "/user/appmeta/NPXS39041", false);
        mnt->Mount(user_appmeta_external_path, "/user/appmeta/external/NPXS39041", false);
        mnt->Mount(user_appmeta_root_path, "/user/appmeta", false);
        const auto app_fonts_path = app0_path / "assets" / "fonts";
        if (std::filesystem::exists(app_fonts_path)) {
            mnt->Mount(app_fonts_path, "/system_ex/app/NPXS20113/bdjstack/lib/fonts", true);
        }
        mnt->Mount(data_self_path, "/data/self", false);
        mnt->Mount(data_path, "/data", false);
        mnt->Mount(system_data_path, "/system_data", false);
        mnt->Mount(temp_path, "/temp0", false);
        mnt->Mount(temp_path, "/temp", false);
        mnt->Mount(download_path, "/download0", false);
        NoteLaunchStageLocked(launch_path, "mount_app0_done",
                              std::string("app0=") + app0_path.string());

        stage = "create_std_handles";
        NoteLaunchStageLocked(launch_path, "create_std_handles_begin");
        Common::Singleton<Core::FileSys::HandleTable>::Instance()->CreateStdHandles();
        NoteLaunchStageLocked(launch_path, "create_std_handles_done");

        stage = "initialize_elf_info";
        NoteLaunchStageLocked(launch_path, "initialize_elf_info_begin");
        InitializeAndroidTitleInfo(app0_path, launch_path);
        LoadAndroidGameSpecificConfig(Common::ElfInfo::Instance().GameSerial());
        NoteLaunchStageLocked(launch_path, "initialize_elf_info_done");

        stage = "linker_singleton";
        NoteLaunchStageLocked(launch_path, "linker_singleton_begin");
        auto* linker = Common::Singleton<Core::Linker>::Instance();
        if (!g_hle_initialized) {
            stage = "init_hle_libs";
            NoteLaunchStageLocked(launch_path, "init_hle_libs_begin");
            Libraries::InitHLELibs(&linker->GetHLESymbols());
            g_hle_initialized = true;
            NoteLaunchStageLocked(launch_path, "init_hle_libs_done");
        }

        stage = "load_module";
        NoteLaunchStageLocked(launch_path, "load_module_begin");
        const int handle = linker->LoadModule(launch_path);
        NoteLaunchStageLocked(launch_path, "load_module_returned",
                              std::string("handle=") + std::to_string(handle));
        if (handle < 0) {
            g_status =
                BuildLaunchFailureStatus(launch_path, stage, "error", "LoadModule returned failure");
            return -3;
        }
        stage = "load_media_modules";
        NoteLaunchStageLocked(launch_path, "load_media_modules_begin");
        const int media_module_result = LoadAndroidAppMediaModulesForLive(*linker, launch_path);
        NoteLaunchStageLocked(launch_path, "load_media_modules_done",
                              std::string("result=") + std::to_string(media_module_result));
        if (Core::Module* module = linker->GetModule(handle)) {
            NoteLaunchStageLocked(launch_path, "patch_guest_begin",
                                  std::string("handle=") + std::to_string(handle));
            PatchPs4StoreOfflineMenu(*module);
            NoteLaunchStageLocked(launch_path, "patch_guest_done",
                                  std::string("handle=") + std::to_string(handle));
        }

        stage = "build_module_status";
        NoteLaunchStageLocked(launch_path, "build_module_status_begin",
                              std::string("handle=") + std::to_string(handle));
        g_last_module_handle = handle;
        g_status = BuildModuleStatus(launch_path, *linker, handle);
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_LAUNCH_STAGE] stage=module_status_done path=%s handle=%d",
                  launch_path.string().c_str(), handle);
        return 0;
    } catch (const std::bad_alloc&) {
        g_status = BuildLaunchFailureStatus(launch_path, stage, "exception", "std::bad_alloc");
        return -4;
    } catch (const std::exception& e) {
        g_status = BuildLaunchFailureStatus(launch_path, stage, "exception", e.what());
        return -4;
    } catch (...) {
        g_status = BuildLaunchFailureStatus(launch_path, stage, "exception", "unknown");
        return -5;
    }
}

extern "C" int executor_lsx4_runtime_relocate_imports() {
    std::lock_guard lock(g_lock);
    if (g_last_module_handle < 0) {
        g_status =
            R"({"state":"relocate_failed","core":"lsx4-native","error":"no loaded module"})";
        return -1;
    }

    std::string stage = "relocate_all_imports";
    try {
        auto* linker = Common::Singleton<Core::Linker>::Instance();
        Core::Module* module = linker->GetModule(g_last_module_handle);
        if (module == nullptr) {
            g_status =
                R"({"state":"relocate_failed","core":"lsx4-native","error":"module handle not found"})";
            return -2;
        }
        const std::filesystem::path path = module->file;
        linker->RelocateAllImports();
        stage = "setup_memory_regions";
        std::string memory_error;
        if (!EnsureMappedEntryMemoryRegions(*module, memory_error)) {
            g_status = std::string(
                           R"({"state":"relocate_failed","core":"lsx4-native","stage":"setup_memory_regions","error":")") +
                       JsonEscape(memory_error) + R"("})";
            return -5;
        }
        InstallBox64HleTrampolines(*module);
        PatchPs4StoreOfflineMenu(*module);
        ApplyUnityGfxThreadingModePatch(*module, "relocate_imports");
        ApplyUnityPreloadLoopExitPatch(*module, "relocate_imports");
        ApplyUnityPreloadControlPatch(*module, "relocate_imports");
        ApplyUnityMonoScriptCacheControlPatch(*module, "relocate_imports");
        ApplyUnityPreloadSchedulerProbePatch(*module, "relocate_imports");
        ApplyUnityPreloadSlot40ProbePatch(*module, "relocate_imports");
        ApplyUnityPreloadEntryProbePatch(*module, "relocate_imports");
        ApplyUnityFrameProbePatch(*module, "relocate_imports");
        ApplyMemoryManagerAllocateDispatchProbePatch(*module, "relocate_imports");
        g_status = BuildRelocateStatus(path, *linker, g_last_module_handle);
        return 0;
    } catch (const std::bad_alloc&) {
        g_status = std::string(R"({"state":"relocate_failed","core":"lsx4-native","stage":")") +
                   JsonEscape(stage) + R"(","exception":"std::bad_alloc"})";
        return -3;
    } catch (const std::exception& e) {
        g_status = std::string(R"({"state":"relocate_failed","core":"lsx4-native","stage":")") +
                   JsonEscape(stage) + R"(","exception":")" + JsonEscape(e.what()) + R"("})";
        return -3;
    } catch (...) {
        g_status = std::string(R"({"state":"relocate_failed","core":"lsx4-native","stage":")") +
                   JsonEscape(stage) + R"(","exception":"unknown"})";
        return -4;
    }
}

extern "C" int executor_lsx4_runtime_prepare_box64_entry_trampoline() {
    std::lock_guard lock(g_lock);
    if (g_root.empty()) {
        g_status =
            R"({"state":"box64_entry_request_failed","core":"lsx4-native","error":"runtime root is not initialized"})";
        return -1;
    }
    if (g_last_module_handle < 0) {
        g_status =
            R"({"state":"box64_entry_request_failed","core":"lsx4-native","error":"no loaded module"})";
        return -2;
    }

    try {
        auto* linker = Common::Singleton<Core::Linker>::Instance();
        Core::Module* module = linker->GetModule(g_last_module_handle);
        if (module == nullptr) {
            g_status =
                R"({"state":"box64_entry_request_failed","core":"lsx4-native","error":"module handle not found"})";
            return -3;
        }
        PatchPs4StoreOfflineMenu(*module);

        g_box64_entry_request = BuildBox64EntryRequest(module->file, *module);
        const std::filesystem::path request_path =
            std::filesystem::path(g_root) / "translator" / "native-box64-entry-request.json";
        const bool written = WriteTextFile(request_path, g_box64_entry_request);

        std::ostringstream status;
        status << "{"
               << R"("state":"box64_entry_trampoline_ready",)"
               << R"("core":"lsx4-native",)"
               << R"("runnable":false,)"
               << R"("requestFile":")" << JsonEscape(request_path.string()) << R"(",)"
               << R"("requestFileWritten":)" << (written ? "true" : "false") << ","
               << R"("entry":")" << Hex64(module->GetEntryAddress()) << R"(",)"
               << R"("procParam":")" << Hex64(module->GetProcParam<std::uint64_t>()) << R"(",)"
               << R"("segmentCount":)" << module->GetModuleInfo().num_segments << ","
               << R"("importLibraryCount":)" << module->GetImportLibs().size() << ","
               << R"("reason":"helper-process Box64 cannot execute parent-process mapped Core::Module memory")"
               << "}";
        g_status = status.str();
        return written ? 0 : -4;
    } catch (const std::exception& e) {
        g_status =
            std::string(R"({"state":"box64_entry_request_failed","core":"lsx4-native","exception":")") +
            JsonEscape(e.what()) + R"("})";
        return -5;
    } catch (...) {
        g_status =
            R"({"state":"box64_entry_request_failed","core":"lsx4-native","exception":"unknown"})";
        return -6;
    }
}

extern "C" const char* executor_lsx4_runtime_box64_entry_request() {
    std::lock_guard lock(g_lock);
    return g_box64_entry_request.c_str();
}

extern "C" int executor_lsx4_runtime_load_embedded_box64(const char* path) {
    std::lock_guard lock(g_lock);
    const std::string raw_path = path ? path : "";
    if (raw_path.empty()) {
        g_box64_embed_info = R"({"loaded":false,"error":"empty path"})";
        g_status = R"({"state":"box64_embedded_load_failed","core":"lsx4-native","error":"empty path"})";
        return -1;
    }
    if (!std::filesystem::exists(raw_path)) {
        g_box64_embed_info =
            std::string(R"({"loaded":false,"path":")") + JsonEscape(raw_path) +
            R"(","error":"path does not exist"})";
        g_status =
            std::string(R"({"state":"box64_embedded_load_failed","core":"lsx4-native","path":")") +
            JsonEscape(raw_path) + R"(","error":"path does not exist"})";
        return -2;
    }

    if (g_box64_embed) {
        dlclose(g_box64_embed);
        g_box64_embed = nullptr;
    }
    g_box64_embed_abi = nullptr;
    g_box64_embed_version = nullptr;
    g_box64_mapped_entry_abi = nullptr;
    g_box64_embed_run_linux_elf = nullptr;
    g_box64_validate_mapped_entry = nullptr;
    g_box64_run_mapped_entry = nullptr;
    g_box64_register_mapped_entry_segments = nullptr;
    g_box64_run_mapped_function = nullptr;
    g_box64_note_named_module = nullptr;
    g_box64_register_guest_signal_handler = nullptr;
    g_box64_queue_guest_signal = nullptr;
    g_box64_queue_guest_signal_for_guest_thread = nullptr;
    g_box64_queue_guest_signal_for_guest_thread_context = nullptr;
    g_box64_run_guest_signal_handler = nullptr;
    g_box64_run_guest_callback = nullptr;
    g_box64_note_current_guest_thread = nullptr;
    g_box64_current_guest_thread = nullptr;
    g_box64_get_current_guest_regs = nullptr;
    g_box64_set_current_guest_regs = nullptr;
    g_box64_dump_guest_threads = nullptr;
    g_box64_arm_sgen_hw_watchpoints = nullptr;
    g_box64_hle_bridge_callback_slot = nullptr;

    const std::filesystem::path embed_path(raw_path);
    const std::filesystem::path fexcore_dependency = embed_path.parent_path() / "libFEXCore.so";
    if (std::filesystem::exists(fexcore_dependency)) {
        void* fexcore_handle = dlopen(fexcore_dependency.string().c_str(), RTLD_NOW | RTLD_GLOBAL);
        if (!fexcore_handle) {
            const char* raw_error = dlerror();
            NativeLog(ANDROID_LOG_WARN,
                      "[EXECUTOR_FEXCORE_DEP] dlopen_failed path=%s error=%s",
                      fexcore_dependency.string().c_str(),
                      raw_error ? raw_error : "unknown");
        } else {
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FEXCORE_DEP] dlopen_ok path=%s",
                      fexcore_dependency.string().c_str());
        }
    }

    g_box64_embed = dlopen(raw_path.c_str(), RTLD_NOW | RTLD_LOCAL);
    if (!g_box64_embed) {
        const char* raw_error = dlerror();
        const std::string error = raw_error ? raw_error : "unknown";
        g_box64_embed_info =
            std::string(R"({"loaded":false,"path":")") + JsonEscape(raw_path) +
            R"(","error":")" + JsonEscape(error) + R"("})";
        g_status =
            std::string(R"({"state":"box64_embedded_load_failed","core":"lsx4-native","path":")") +
            JsonEscape(raw_path) + R"(","error":")" + JsonEscape(error) + R"("})";
        return -3;
    }

    g_box64_embed_abi =
        reinterpret_cast<box64_cstr_fn>(dlsym(g_box64_embed, "executor_box64_embed_abi"));
    g_box64_embed_version =
        reinterpret_cast<box64_cstr_fn>(dlsym(g_box64_embed, "executor_box64_embed_version"));
    g_box64_mapped_entry_abi =
        reinterpret_cast<box64_cstr_fn>(dlsym(g_box64_embed, "executor_box64_embed_mapped_entry_abi"));
    g_box64_embed_run_linux_elf = reinterpret_cast<box64_run_linux_elf_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_run_linux_elf"));
    g_box64_validate_mapped_entry = reinterpret_cast<box64_validate_mapped_entry_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_validate_mapped_entry"));
    g_box64_run_mapped_entry = reinterpret_cast<box64_validate_mapped_entry_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_run_mapped_entry"));
    if (g_box64_run_mapped_entry) {
        Dl_info run_info {};
        const int run_info_ok =
            dladdr(reinterpret_cast<void*>(g_box64_run_mapped_entry), &run_info);
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_EMBED_RUN_SYMBOL] phase=dlsym fn=%p dladdr=%d so=%s base=%p "
                  "symbol=%s sym=%p",
                  reinterpret_cast<void*>(g_box64_run_mapped_entry), run_info_ok,
                  run_info.dli_fname ? run_info.dli_fname : "<none>", run_info.dli_fbase,
                  run_info.dli_sname ? run_info.dli_sname : "<none>", run_info.dli_saddr);
    }
    g_box64_register_mapped_entry_segments =
        reinterpret_cast<box64_register_mapped_entry_segments_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_register_mapped_entry_segments"));
    g_box64_run_mapped_function = reinterpret_cast<box64_run_mapped_function_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_run_mapped_function"));
    g_box64_note_named_module = reinterpret_cast<box64_note_named_module_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_note_named_module"));
    g_box64_register_guest_signal_handler =
        reinterpret_cast<box64_register_guest_signal_handler_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_register_guest_signal_handler"));
    g_box64_queue_guest_signal = reinterpret_cast<box64_queue_guest_signal_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_queue_guest_signal"));
    g_box64_queue_guest_signal_for_guest_thread =
        reinterpret_cast<box64_queue_guest_signal_for_guest_thread_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_queue_guest_signal_for_guest_thread"));
    g_box64_queue_guest_signal_for_guest_thread_context =
        reinterpret_cast<box64_queue_guest_signal_for_guest_thread_context_fn>(dlsym(
            g_box64_embed, "executor_box64_embed_queue_guest_signal_for_guest_thread_context"));
    g_box64_run_guest_signal_handler =
        reinterpret_cast<box64_run_guest_signal_handler_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_run_guest_signal_handler"));
    g_box64_run_guest_callback =
        reinterpret_cast<box64_run_guest_callback_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_run_guest_callback"));
    g_box64_note_current_guest_thread =
        reinterpret_cast<box64_note_current_guest_thread_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_note_current_guest_thread"));
    g_box64_current_guest_thread = reinterpret_cast<box64_current_guest_thread_fn>(
        dlsym(g_box64_embed, "executor_box64_embed_current_guest_thread"));
    g_box64_get_current_guest_regs =
        reinterpret_cast<box64_get_current_guest_regs_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_get_current_guest_regs"));
    g_box64_set_current_guest_regs =
        reinterpret_cast<box64_set_current_guest_regs_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_set_current_guest_regs"));
    g_box64_dump_guest_threads =
        reinterpret_cast<box64_dump_guest_threads_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_dump_guest_threads"));
    g_box64_arm_sgen_hw_watchpoints =
        reinterpret_cast<box64_arm_sgen_hw_watchpoints_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_arm_sgen_hw_watchpoints"));
    g_box64_arm_addr_software_watch =
        reinterpret_cast<box64_arm_addr_software_watch_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_arm_addr_software_watch"));
    g_box64_arm_oneshot_region_watch =
        reinterpret_cast<box64_arm_addr_software_watch_fn>(
            dlsym(g_box64_embed, "executor_arm_oneshot_region_watch"));
    g_box64_sw_watch_rearm =
        reinterpret_cast<box64_sw_watch_rearm_fn>(
            dlsym(g_box64_embed, "executor_box64_embed_sw_watch_rearm"));
    g_box64_hle_bridge_callback_slot = reinterpret_cast<box64_hle_bridge_callback_fn*>(
        dlsym(g_box64_embed, "executor_box64_hle_bridge_callback"));
    if (!g_box64_embed_abi || !g_box64_embed_version || !g_box64_embed_run_linux_elf ||
        !g_box64_mapped_entry_abi || !g_box64_validate_mapped_entry || !g_box64_run_mapped_entry ||
        !g_box64_register_mapped_entry_segments || !g_box64_run_mapped_function ||
        !g_box64_note_current_guest_thread || !g_box64_current_guest_thread) {
        g_box64_embed_info =
            std::string(R"({"loaded":false,"path":")") + JsonEscape(raw_path) +
            R"(","error":"missing executor Box64 embed ABI symbols"})";
        g_status =
            std::string(R"({"state":"box64_embedded_load_failed","core":"lsx4-native","path":")") +
            JsonEscape(raw_path) + R"(","error":"missing executor Box64 embed ABI symbols"})";
        dlclose(g_box64_embed);
        g_box64_embed = nullptr;
        return -4;
    }
    if (g_box64_hle_bridge_callback_slot) {
        *g_box64_hle_bridge_callback_slot = ExecutorBox64HleBridgeCallback;
    }

    g_box64_embed_info =
        BuildBox64EmbedInfo(raw_path, g_box64_embed_abi(), g_box64_embed_version());
    g_status =
        std::string(R"({"state":"box64_embedded_loaded","core":"lsx4-native","box64":)") +
        g_box64_embed_info + R"(})";
    return 0;
}

extern "C" const char* executor_lsx4_runtime_embedded_box64_info() {
    std::lock_guard lock(g_lock);
    return g_box64_embed_info.c_str();
}

extern "C" int executor_lsx4_runtime_validate_embedded_box64_mapped_entry() {
    std::lock_guard lock(g_lock);
    if (!g_box64_embed || !g_box64_validate_mapped_entry) {
        g_box64_mapped_entry_info =
            R"({"validated":false,"error":"embedded Box64 is not loaded"})";
        g_status =
            R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","error":"embedded Box64 is not loaded"})";
        return -1;
    }
    if (g_last_module_handle < 0) {
        g_box64_mapped_entry_info =
            R"({"validated":false,"error":"no loaded module"})";
        g_status =
            R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","error":"no loaded module"})";
        return -2;
    }

    try {
        auto* linker = Common::Singleton<Core::Linker>::Instance();
        Core::Module* module = linker->GetModule(g_last_module_handle);
        if (module == nullptr) {
            g_box64_mapped_entry_info =
                R"({"validated":false,"error":"module handle not found"})";
            g_status =
                R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","error":"module handle not found"})";
            return -3;
        }
        PatchPs4StoreOfflineMenu(*module);
        ApplyUnityGfxThreadingModePatch(*module, "validate_mapped_entry");
        ApplyUnityPreloadControlPatch(*module, "validate_mapped_entry");
        ApplyUnityMonoScriptCacheControlPatch(*module, "validate_mapped_entry");
        ApplyUnityPreloadSchedulerProbePatch(*module, "validate_mapped_entry");
        ApplyUnityPreloadSlot40ProbePatch(*module, "validate_mapped_entry");
        ApplyUnityPreloadEntryProbePatch(*module, "validate_mapped_entry");
        ApplyUnityFrameProbePatch(*module, "validate_mapped_entry");
        ApplyMemoryManagerAllocateDispatchProbePatch(*module, "validate_mapped_entry");

        ExecutorBox64MappedEntryRequest request{};
        std::string error;
        if (!BuildMappedEntryRequestFromModule(*module, request, error)) {
            g_box64_mapped_entry_info =
                std::string(R"({"validated":false,"error":")") + JsonEscape(error) + R"("})";
            g_status =
                std::string(R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","error":")") +
                JsonEscape(error) + R"("})";
            return -4;
        }

        char validation_error[256] = {};
        const int result =
            g_box64_validate_mapped_entry(&request, validation_error, sizeof(validation_error));
        std::ostringstream info;
        info << "{"
             << R"("validated":)" << (result == 0 ? "true" : "false") << ","
             << R"("result":)" << result << ","
             << R"("message":")" << JsonEscape(validation_error) << R"(",)"
             << R"("mappedEntryAbi":")"
             << JsonEscape(g_box64_mapped_entry_abi ? g_box64_mapped_entry_abi() : "") << R"(",)"
             << R"("entry":")" << Hex64(request.entry) << R"(",)"
             << R"("procParam":")" << Hex64(request.proc_param) << R"(",)"
             << R"("stackBase":")" << Hex64(request.stack_base) << R"(",)"
             << R"("stackSize":")" << Hex64(request.stack_size) << R"(",)"
             << R"("tlsImageAddr":")" << Hex64(request.tls_image_addr) << R"(",)"
             << R"("tlsImageSize":)" << request.tls_image_size << ","
             << R"("tcbBase":")" << Hex64(request.tcb_base) << R"(",)"
             << R"("entryParams":")" << Hex64(request.entry_params) << R"(",)"
             << R"("exitFunc":")" << Hex64(request.exit_func) << R"(",)"
             << R"("hleTrampolineBase":")" << Hex64(request.hle_trampoline_base) << R"(",)"
             << R"("hleTrampolineSize":")" << Hex64(request.hle_trampoline_size) << R"(",)"
             << R"("timeoutMs":)" << request.timeout_ms << ","
             << R"("segmentCount":)" << request.segment_count << ","
             << R"("next_step":"attempt executor_box64_embed_run_mapped_entry and capture the first HLE/TLS boundary")"
             << "}";
        g_box64_mapped_entry_info = info.str();

        std::ostringstream status;
        status << "{"
               << R"("state":")"
               << (result == 0 ? "box64_mapped_entry_validated"
                               : "box64_mapped_entry_validation_failed")
               << R"(",)"
               << R"("core":"lsx4-native",)"
               << R"("box64MappedEntry":)" << g_box64_mapped_entry_info << "}";
        g_status = status.str();
        return result;
    } catch (const std::exception& e) {
        g_box64_mapped_entry_info =
            std::string(R"({"validated":false,"exception":")") + JsonEscape(e.what()) + R"("})";
        g_status =
            std::string(R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","exception":")") +
            JsonEscape(e.what()) + R"("})";
        return -5;
    } catch (...) {
        g_box64_mapped_entry_info = R"({"validated":false,"exception":"unknown"})";
        g_status =
            R"({"state":"box64_mapped_entry_validation_failed","core":"lsx4-native","exception":"unknown"})";
        return -6;
    }
}

extern "C" const char* executor_lsx4_runtime_embedded_box64_mapped_entry_info() {
    std::lock_guard lock(g_lock);
    return g_box64_mapped_entry_info.c_str();
}

extern "C" int executor_lsx4_runtime_run_jit_mapped_entry() {
    std::unique_lock lock(g_lock);
    if (RuntimeGuestJitActive()) {
        const bool launch_entry_requested =
            g_jit_launch_entry_requested.exchange(false, std::memory_order_acq_rel);
        const auto foreground_opt_in =
            std::filesystem::path(g_root) / "run-jit-foreground-mapped-entry";
        if (!launch_entry_requested && !std::filesystem::exists(foreground_opt_in)) {
            g_box64_mapped_entry_info =
                R"({"attempted":false,"skipped":true,"mode":"jit_aarch64_jit","reason":"jit_uses_launch_game_entry; old Box64/FEX mapped-entry foreground path is disabled unless run-jit-foreground-mapped-entry exists"})";
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_JIT_ENTRY_RUN] result=skipped reason=foreground_mapped_entry_disabled marker=%s",
                      foreground_opt_in.string().c_str());
            return 0;
        }
    }
    if (!RuntimeGuestJitActive() && (!g_box64_embed || !g_box64_run_mapped_entry)) {
        g_box64_mapped_entry_info =
            R"({"attempted":false,"error":"embedded Box64 is not loaded"})";
        g_status =
            R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":"embedded Box64 is not loaded"})";
        return -1;
    }
    if (g_last_module_handle < 0) {
        g_box64_mapped_entry_info =
            R"({"attempted":false,"error":"no loaded module"})";
        g_status =
            R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":"no loaded module"})";
        return -2;
    }

    try {
        auto* linker = Common::Singleton<Core::Linker>::Instance();
        Core::Module* module = linker->GetModule(g_last_module_handle);
        if (module == nullptr) {
            g_box64_mapped_entry_info =
                R"({"attempted":false,"error":"module handle not found"})";
            g_status =
                R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":"module handle not found"})";
            return -3;
        }

        PatchPs4StoreOfflineMenu(*module);
        ApplyUnityGfxThreadingModePatch(*module, "run_mapped_entry");
        ApplyUnityPreloadControlPatch(*module, "run_mapped_entry");
        ApplyUnityMonoScriptCacheControlPatch(*module, "run_mapped_entry");
        ApplyUnityPreloadSchedulerProbePatch(*module, "run_mapped_entry");
        ApplyUnityPreloadSlot40ProbePatch(*module, "run_mapped_entry");
        ApplyUnityPreloadEntryProbePatch(*module, "run_mapped_entry");
        ApplyUnityFrameProbePatch(*module, "run_mapped_entry");
        ApplyMemoryManagerAllocateDispatchProbePatch(*module, "run_mapped_entry");

        ExecutorBox64MappedEntryRequest request{};
        std::string error;
        if (!BuildMappedEntryRequestFromModule(*module, request, error)) {
            g_box64_mapped_entry_info =
                std::string(R"({"attempted":false,"error":")") + JsonEscape(error) + R"("})";
            g_status =
                std::string(R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":")") +
                JsonEscape(error) + R"("})";
            return -4;
        }

        if (RuntimeGuestJitActive()) {
            // PC Linker::Execute enters bootstrap from an already-created Game:Main.  Building the
            // main request first establishes eboot EntryParams, static TLS and the primary TCB;
            // only then may guest PRX initializers run.  Complete the same bootstrap with the
            // SceGnmDriver direct-memory mapping, then refresh the request for newly loaded PRX
            // executable segments before entering eboot.
            std::string bootstrap_error;
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_JIT_PROCESS_BOOTSTRAP] stage=begin mode=full");
            lock.unlock();
            const bool bootstrap_ok = EnsureMappedEntryProcessBootstrap(bootstrap_error);
            lock.lock();
            NativeLog(bootstrap_ok ? ANDROID_LOG_INFO : ANDROID_LOG_ERROR,
                      "[EXECUTOR_JIT_PROCESS_BOOTSTRAP] stage=result ok=%d error=%s",
                      bootstrap_ok ? 1 : 0, bootstrap_error.c_str());
            if (!bootstrap_ok) {
                g_box64_mapped_entry_info =
                    std::string(R"({"attempted":false,"error":"process bootstrap failed: )") +
                    JsonEscape(bootstrap_error) + R"("})";
                g_status =
                    std::string(R"({"state":"jit_process_bootstrap_failed","core":"lsx4-native","error":")") +
                    JsonEscape(bootstrap_error) + R"("})";
                return -8;
            }

            std::string refreshed_error;
            if (!BuildMappedEntryRequestFromModule(*module, request, refreshed_error)) {
                g_box64_mapped_entry_info =
                    std::string(R"({"attempted":false,"error":")") +
                    JsonEscape(refreshed_error) + R"("})";
                g_status =
                    std::string(R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":")") +
                    JsonEscape(refreshed_error) + R"("})";
                return -4;
            }
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_MAPPED_ENTRY_REQUEST_REFRESH] phase=jit_post_bootstrap "
                      "entry=%p segments=%u tcb=%p",
                      reinterpret_cast<void*>(request.entry), request.segment_count,
                      reinterpret_cast<void*>(request.tcb_base));
        }

        if (RuntimeGuestJitActive()) {
            std::ostringstream running;
            running << "{"
                    << R"("attempted":true,)"
                    << R"("running":true,)"
                    << R"("mode":"jit_aarch64_jit",)"
                    << R"("entry":")" << Hex64(request.entry) << R"(",)"
                    << R"("entryParams":")" << Hex64(request.entry_params) << R"(",)"
                    << R"("exitFunc":")" << Hex64(request.exit_func) << R"(",)"
                    << R"("procParam":")" << Hex64(request.proc_param) << R"(",)"
                    << R"("stackBase":")" << Hex64(request.stack_base) << R"(",)"
                    << R"("stackSize":")" << Hex64(request.stack_size) << R"(",)"
                    << R"("tlsImageAddr":")" << Hex64(request.tls_image_addr) << R"(",)"
                    << R"("tlsImageSize":)" << request.tls_image_size << ","
                    << R"("tcbBase":")" << Hex64(request.tcb_base) << R"(",)"
                    << R"("segmentCount":)" << request.segment_count << ","
                    << R"("next_step":"JIT is executing the loaded module entry through the reconstructed AArch64 JIT route")"
                    << "}";
            g_box64_mapped_entry_info = running.str();
            g_status = std::string(
                           R"({"state":"jit_mapped_entry_running","core":"lsx4-native","guestEntryAttempted":true,"guestEntryCompleted":false,"jit":)") +
                       g_box64_mapped_entry_info + "}";
            WriteTextFile(std::filesystem::path(g_root) / "translator" /
                              "last-jit-entry-run.json",
                          g_box64_mapped_entry_info);

            int result = 0;
            std::string exception_text;
            auto* primary_guest_thread = Libraries::Kernel::g_curthread;
            lock.unlock();
            std::thread guest_entry_thread([&]() {
                try {
                    if (primary_guest_thread != nullptr) {
                        Libraries::Kernel::g_curthread = primary_guest_thread;
                        Common::SetCurrentThreadName(primary_guest_thread->name.c_str());
                        // The primary guest Pthread is allocated while the mapped-entry request is
                        // prepared, but JIT executes it on this dedicated native worker.  A
                        // normal guest pthread binds NativeThread from RunThread(); the primary
                        // path previously skipped that step, leaving GetHandle()==0.  Mono could
                        // then enumerate Game:Main for stop-the-world, but pthread_kill(0, SIGUSR1)
                        // never delivered its suspend handler and the initiator waited forever for
                        // the missing ACK.  Bind the Pthread to the worker that actually owns its
                        // JIT guest state, matching the reference's 1:1 native thread model.
                        primary_guest_thread->native_thr.Initialize();
                        // std::thread inherits the creator's host signal mask.  The Android launch
                        // thread has SIGURG blocked, so Mono's suspend signal was successfully
                        // queued to Game:Main but remained pending forever.  Upstream Linker::Execute
                        // and every regular RunThread clear the inherited mask before guest entry;
                        // preserve that exact contract for JIT's dedicated primary worker.
                        sigset_t empty_signal_mask;
                        sigemptyset(&empty_signal_mask);
                        const int signal_mask_rc =
                            pthread_sigmask(SIG_SETMASK, &empty_signal_mask, nullptr);
                        if (primary_guest_thread->tcb != nullptr) {
                            Core::SetTcbBase(primary_guest_thread->tcb);
                        }
                        NativeLog(ANDROID_LOG_INFO,
                                  "[EXECUTOR_JIT_PRIMARY_THREAD] bound thread=%p name=%s "
                                  "native=0x%zx tcb=%p signalMaskRc=%d",
                                  static_cast<void*>(primary_guest_thread),
                                  primary_guest_thread->name.c_str(),
                                  static_cast<std::size_t>(
                                      primary_guest_thread->native_thr.GetHandle()),
                                  static_cast<void*>(primary_guest_thread->tcb), signal_mask_rc);
                    }
                    Executor::Jit::LsxEntryPacket ctx{};
                    ctx.args[0] = request.entry_params;
                    ctx.args[1] = request.exit_func;
                    ctx.arg_count = 2;
                    // Main-entry is not a normal ExecuteGuest call. Upstream shadPS4 reaches
                    // eboot through RunMainEntry: RDI=params, RSI=ProgramExitFunc, and the first
                    // two EntryParams qwords are copied to the initial guest stack before a jump
                    // into the eboot entry. JIT must reconstruct that process-entry frame;
                    // ordinary HLE/guest calls still use the LsxEntryPacket stack-argument
                    // contract.
                    ctx.stack_args_enabled = 2;
                    ctx.segment_base = request.tcb_base;
                    ctx.stack_base = request.stack_base;
                    ctx.stack_size = request.stack_size;
                    // A real process entry should leave via ProgramExitFunc or the eboot exit
                    // chain, not by a managed helper tail-returning into JIT's sentinel.
                    // Keep the sentinel enabled for explicit JIT helper exits, but the
                    // main-entry stack above prevents ordinary tail-call icalls from becoming a
                    // false mapped-entry completion.
                    ctx.allow_guest_return_sentinel = 1;
                    const std::uint64_t guest_result =
                        Executor::Jit::RunArm64Translation(request.entry, ctx);
                    result = static_cast<int>(guest_result);
                } catch (const std::exception& e) {
                    exception_text = e.what();
                    result = -70;
                } catch (...) {
                    exception_text = "unknown";
                    result = -71;
                }
            });
            guest_entry_thread.join();
            lock.lock();

            std::ostringstream info;
            info << "{"
                 << R"("attempted":true,)"
                 << R"("completed":)" << (result >= 0 ? "true" : "false") << ","
                 << R"("result":)" << result << ","
                 << R"("exception":")" << JsonEscape(exception_text) << R"(",)"
                 << R"("entry":")" << Hex64(request.entry) << R"(",)"
                 << R"("entryParams":")" << Hex64(request.entry_params) << R"(",)"
                 << R"("exitFunc":")" << Hex64(request.exit_func) << R"(",)"
                 << R"("procParam":")" << Hex64(request.proc_param) << R"(",)"
                 << R"("stackBase":")" << Hex64(request.stack_base) << R"(",)"
                 << R"("stackSize":")" << Hex64(request.stack_size) << R"(",)"
                 << R"("tcbBase":")" << Hex64(request.tcb_base) << R"(",)"
                 << R"("next_step":"expand JIT opcode/helper coverage for the reported guest block")"
                 << "}";
            g_box64_mapped_entry_info = info.str();
            WriteTextFile(std::filesystem::path(g_root) / "translator" /
                              "last-jit-entry-run.json",
                          g_box64_mapped_entry_info);
            g_status = std::string(
                           R"({"state":")") +
                       (result >= 0 ? "jit_mapped_entry_exited"
                                    : "jit_mapped_entry_failed") +
                       R"(","core":"lsx4-native","jit":)" +
                       g_box64_mapped_entry_info + "}";
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_JIT_ENTRY_RUN] result=%d exception=%s info=%s",
                      result, exception_text.c_str(), g_box64_mapped_entry_info.c_str());
            return result;
        }

        {
            std::ostringstream running;
            running << "{"
                    << R"("attempted":true,)"
                    << R"("running":true,)"
                    << R"("mode":"in_process_background",)"
                    << R"("mappedEntryAbi":")"
                    << JsonEscape(g_box64_mapped_entry_abi ? g_box64_mapped_entry_abi() : "")
                    << R"(",)"
                    << R"("entry":")" << Hex64(request.entry) << R"(",)"
                    << R"("entryParams":")" << Hex64(request.entry_params) << R"(",)"
                    << R"("exitFunc":")" << Hex64(request.exit_func) << R"(",)"
                    << R"("hleTrampolineBase":")" << Hex64(request.hle_trampoline_base) << R"(",)"
                    << R"("hleTrampolineSize":")" << Hex64(request.hle_trampoline_size) << R"(",)"
                    << R"("mappedEntryBoundaryProbe":)"
                    << SnapshotMappedEntryBoundaryProbeJson() << ","
                    << R"("flags":)" << request.flags << ","
                    << R"("procParam":")" << Hex64(request.proc_param) << R"(",)"
                    << R"("stackBase":")" << Hex64(request.stack_base) << R"(",)"
                    << R"("stackSize":")" << Hex64(request.stack_size) << R"(",)"
                    << R"("tlsImageAddr":")" << Hex64(request.tls_image_addr) << R"(",)"
                    << R"("tlsImageSize":)" << request.tls_image_size << ","
                    << R"("tcbBase":")" << Hex64(request.tcb_base) << R"(",)"
                    << R"("segmentCount":)" << request.segment_count << ","
                    << R"("next_step":"guest is running in-process; capture VideoOut SubmitFlip through Android surface")"
                    << "}";
            g_box64_mapped_entry_info = running.str();
            g_status = std::string(
                           R"({"state":"box64_mapped_entry_running","core":"lsx4-native","guestEntryAttempted":true,"guestEntryCompleted":false,"box64MappedEntry":)") +
                       g_box64_mapped_entry_info + "}";
            WriteTextFile(std::filesystem::path(g_root) / "translator" /
                              "last-mapped-entry-run.json",
                          g_box64_mapped_entry_info);
        }

        char run_message[65536] = {};
        lock.unlock();
        std::string bootstrap_error;
        if (!EnsureMappedEntryProcessBootstrap(bootstrap_error)) {
            lock.lock();
            g_box64_mapped_entry_info =
                std::string(R"({"attempted":false,"error":")") +
                JsonEscape(bootstrap_error) + R"("})";
            g_status =
                std::string(R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":")") +
                JsonEscape(bootstrap_error) + R"("})";
            return -1;
        }

        // Bootstrap can synchronously load PRX modules such as libc/libSceFios2 and register their
        // executable segments. Rebuild the FEX request after bootstrap so QueryGuestExecutableRange
        // receives a complete snapshot instead of wiping those late registrations with the older
        // pre-bootstrap segment list.
        std::string refreshed_error;
        if (!BuildMappedEntryRequestFromModule(*module, request, refreshed_error)) {
            lock.lock();
            g_box64_mapped_entry_info =
                std::string(R"({"attempted":false,"error":")") +
                JsonEscape(refreshed_error) + R"("})";
            g_status =
                std::string(R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","error":")") +
                JsonEscape(refreshed_error) + R"("})";
            return -4;
        }
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_REQUEST_REFRESH] phase=post_bootstrap entry=%p "
                  "segments=%u hle=%p+0x%llx",
                  reinterpret_cast<void*>(request.entry), request.segment_count,
                  reinterpret_cast<void*>(request.hle_trampoline_base),
                  static_cast<unsigned long long>(request.hle_trampoline_size));
        PatchMappedEntryZeroPltCalls(request);
        BeginMappedEntryBoundaryProbe("loader", *module, request);
        ScopedBox64GuestEntryActive guest_entry_scope("loader_entry");
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_CALL] phase=loader event=before fn=%p request=%p "
                  "entry=%p entry_params=%p exit=%p stack=%p stack_size=0x%llx",
                  reinterpret_cast<void*>(g_box64_run_mapped_entry),
                  static_cast<void*>(&request), reinterpret_cast<void*>(request.entry),
                  reinterpret_cast<void*>(request.entry_params),
                  reinterpret_cast<void*>(request.exit_func),
                  reinterpret_cast<void*>(request.stack_base),
                  static_cast<unsigned long long>(request.stack_size));
        {
            Dl_info run_info {};
            const int run_info_ok =
                dladdr(reinterpret_cast<void*>(g_box64_run_mapped_entry), &run_info);
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_EMBED_RUN_SYMBOL] phase=loader-before fn=%p dladdr=%d so=%s "
                      "base=%p symbol=%s sym=%p",
                      reinterpret_cast<void*>(g_box64_run_mapped_entry), run_info_ok,
                      run_info.dli_fname ? run_info.dli_fname : "<none>", run_info.dli_fbase,
                      run_info.dli_sname ? run_info.dli_sname : "<none>", run_info.dli_saddr);
        }
        // Run the eboot's loader/guest entry on a PURE NATIVE thread, NOT the ART-attached caller
        // (MainActivity's Java automation thread). If the guest runs on a thread in ART's thread
        // list, ART's GC root checkpoint (MarkCompact::CheckpointMarkThreadRoots -> Thread::VisitRoots
        // -> StackVisitor::WalkStack) follows the box64/guest frames -> guest pointer where an
        // ArtMethod* is expected -> SIGSEGV in HeapTaskDaemon ~25s into managed execution. A native
        // pthread is invisible to ART; the caller blocks in join() with only clean managed frames.
        int result = 0;
        {
            auto* primary_guest_thread = Libraries::Kernel::g_curthread;
            std::thread guest_entry_thread([&]() {
                if (primary_guest_thread != nullptr) {
                    Libraries::Kernel::g_curthread = primary_guest_thread;
                    Common::SetCurrentThreadName(primary_guest_thread->name.c_str());
                    if (primary_guest_thread->tcb != nullptr) {
                        Core::SetTcbBase(primary_guest_thread->tcb);
                    }
                    NativeLog(ANDROID_LOG_INFO,
                              "[EXECUTOR_MAPPED_ENTRY_THREAD] phase=loader bound thread=%p "
                              "name=%s tcb=%p",
                              static_cast<void*>(primary_guest_thread),
                              primary_guest_thread->name.c_str(),
                              static_cast<void*>(primary_guest_thread->tcb));
                } else {
                    NativeLog(ANDROID_LOG_WARN,
                              "[EXECUTOR_MAPPED_ENTRY_THREAD] phase=loader no_primary_thread");
                }
                result = g_box64_run_mapped_entry(&request, run_message, sizeof(run_message));
            });
            guest_entry_thread.join();
        }
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_CALL] phase=loader event=after result=%d message=%s",
                  result, run_message);
        const std::string boundary_probe =
            FinishMappedEntryBoundaryProbe("loader", result, run_message);
        lock.lock();
        const bool signaled = result >= 128 && result <= 191;
        const bool timeout = result == -124;
        const bool exited = result >= 0 && result < 128;
        const bool completed = result == 0;

        std::ostringstream info;
        info << "{"
             << R"("attempted":true,)"
             << R"("completed":)" << (completed ? "true" : "false") << ","
             << R"("exited":)" << (exited ? "true" : "false") << ","
             << R"("signaled":)" << (signaled ? "true" : "false") << ","
             << R"("timeout":)" << (timeout ? "true" : "false") << ","
             << R"("result":)" << result << ","
             << R"("message":")" << JsonEscape(run_message) << R"(",)"
             << R"("mappedEntryAbi":")"
             << JsonEscape(g_box64_mapped_entry_abi ? g_box64_mapped_entry_abi() : "") << R"(",)"
             << R"("entry":")" << Hex64(request.entry) << R"(",)"
             << R"("entryParams":")" << Hex64(request.entry_params) << R"(",)"
             << R"("exitFunc":")" << Hex64(request.exit_func) << R"(",)"
             << R"("hleTrampolineBase":")" << Hex64(request.hle_trampoline_base) << R"(",)"
             << R"("hleTrampolineSize":")" << Hex64(request.hle_trampoline_size) << R"(",)"
             << R"("mappedEntryBoundaryProbe":)" << boundary_probe << ","
             << R"("procParam":")" << Hex64(request.proc_param) << R"(",)"
             << R"("stackBase":")" << Hex64(request.stack_base) << R"(",)"
             << R"("stackSize":")" << Hex64(request.stack_size) << R"(",)"
             << R"("tlsImageAddr":")" << Hex64(request.tls_image_addr) << R"(",)"
             << R"("tlsImageSize":)" << request.tls_image_size << ","
             << R"("tcbBase":")" << Hex64(request.tcb_base) << R"(",)"
             << R"("segmentCount":)" << request.segment_count << ","
             << R"("next_step":"replace direct arm64 HLE import pointers with Box64-callable x86 trampolines")"
             << "}";
        g_box64_mapped_entry_info = info.str();
        WriteTextFile(std::filesystem::path(g_root) / "translator" /
                          "last-mapped-entry-run.json",
                      g_box64_mapped_entry_info);

        if (ProcessPendingLoadExecLocked(lock, g_box64_mapped_entry_info)) {
            return result;
        }

        std::ostringstream status;
        status << "{"
               << R"("state":")"
               << (completed ? "box64_mapped_entry_exited"
                             : (signaled ? "box64_mapped_entry_signaled"
                                         : (timeout ? "box64_mapped_entry_timeout"
                                                    : "box64_mapped_entry_failed")))
               << R"(",)"
               << R"("core":"lsx4-native",)"
               << R"("guestEntryAttempted":true,)"
               << R"("guestEntryCompleted":)" << (completed ? "true" : "false") << ","
               << R"("box64MappedEntry":)" << g_box64_mapped_entry_info << "}";
        g_status = status.str();
        return result;
    } catch (const std::exception& e) {
        g_box64_mapped_entry_info =
            std::string(R"({"attempted":false,"exception":")") + JsonEscape(e.what()) + R"("})";
        g_status =
            std::string(R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","exception":")") +
            JsonEscape(e.what()) + R"("})";
        return -5;
    } catch (...) {
        g_box64_mapped_entry_info = R"({"attempted":false,"exception":"unknown"})";
        g_status =
            R"({"state":"box64_mapped_entry_run_failed","core":"lsx4-native","exception":"unknown"})";
        return -6;
    }
}

extern "C" int executor_lsx4_runtime_run_embedded_box64_mapped_entry() {
    return executor_lsx4_runtime_run_jit_mapped_entry();
}
